(() => {
  "use strict";

  const SCRIPT_WIN = window;
  const WIN = window.parent || window;
  const DOC = WIN.document;
  const NS = "mes-padding-calc-01";
  const PANEL_ID = `${NS}-panel`;
  const MIN_PILL_ID = `${NS}-min-pill`;
  const STYLE_ID = `${NS}-style`;
  const PREVIEW_STYLE_ID = `${NS}-preview-style`;
  const TYPE_PREVIEW_STYLE_ID = `${NS}-type-preview-style`;
  const TYPE_LIVE_STYLE_ID = `${NS}-type-live-style`;
  const TYPE_LIVE_KEY = "freesia-override-live-typography-v1";
  const SPACING_LIVE_STYLE_ID = `${NS}-spacing-live-style`;
  const SCROLL_LIVE_STYLE_ID = `${NS}-scroll-live-style`;
  const AVATAR_LIVE_STYLE_ID = `${NS}-avatar-live-style`;
  const EXTRA_LIVE_KEY = "freesia-override-live-layout-v1";
  const AVATAR_PREVIEW_STYLE_ID = `${NS}-avatar-preview-style`;
  const SCROLL_PREVIEW_STYLE_ID = `${NS}-scroll-preview-style`;
  const SCROLL_WIDTH_BEGIN = "/* § FREESIA SCROLLBAR WIDTH · BEGIN */";
  const SCROLL_WIDTH_END = "/* § FREESIA SCROLLBAR WIDTH · END */";
  const SCROLL_CHAT_WIDTH_BEGIN = "/* § FREESIA CHAT SCROLLBAR WIDTH · BEGIN */";
  const SCROLL_CHAT_WIDTH_END = "/* § FREESIA CHAT SCROLLBAR WIDTH · END */";
  const SCROLL_GLOBAL_WIDTH_BEGIN = "/* § FREESIA GLOBAL SCROLLBAR WIDTH · BEGIN */";
  const SCROLL_GLOBAL_WIDTH_END = "/* § FREESIA GLOBAL SCROLLBAR WIDTH · END */";
  const SCROLL_CHAT_GUTTER_BEGIN = "/* § FREESIA CHAT SCROLLBAR GUTTER · BEGIN */";
  const SCROLL_CHAT_GUTTER_END = "/* § FREESIA CHAT SCROLLBAR GUTTER · END */";
  const SCROLL_GLOBAL_GUTTER_BEGIN = "/* § FREESIA GLOBAL SCROLLBAR GUTTER · BEGIN */";
  const SCROLL_GLOBAL_GUTTER_END = "/* § FREESIA GLOBAL SCROLLBAR GUTTER · END */";
  const SCROLL_LAYOUT_BEGIN = "/* § FREESIA CHAT LAYOUT · BEGIN */";
  const SCROLL_LAYOUT_END = "/* § FREESIA CHAT LAYOUT · END */";
  const AVATAR_BEGIN = "/* § FREESIA AVATAR POSITION · BEGIN */";
  const AVATAR_END = "/* § FREESIA AVATAR POSITION · END */";
  const TYPE_BEGIN = "/* § FREESIA TYPOGRAPHY · BEGIN */";
  const TYPE_END = "/* § FREESIA TYPOGRAPHY · END */";

  // § 正文排版 · 一套规则驱动预览、常驻和 CSS 写入，避免样式补丁。
  function normalizedTypography(input = {}) {
    const lh = Number(input.lineHeight);
    const ls = Number(input.letterSpacing);
    return {
      lineHeight: Number.isFinite(lh) ? Math.min(2.2, Math.max(1.2, Math.round(lh * 100) / 100)) : 1.6,
      letterSpacing: Number.isFinite(ls) ? Math.min(5, Math.max(-1, Math.round(ls * 10) / 10)) : 0,
      paragraphIndent: input.paragraphIndent === "2em" ? "2em" : "keep",
    };
  }
  function typographyRules(input) {
    const values = normalizedTypography(input);
    const selector = "html body #sheld#sheld #chat .mes .mes_block .mes_text";
    let css = `${selector} {\n  line-height: ${values.lineHeight} !important;\n  letter-spacing: ${values.letterSpacing}px !important;\n}`;
    if (values.paragraphIndent === "2em") css += `\n/* § 正文段落首行缩进 */\n${selector} > p { text-indent: 2em !important; }`;
    return css;
  }
  function readLiveTypography() {
    try {
      const data = JSON.parse(WIN.localStorage.getItem(TYPE_LIVE_KEY) || "null");
      return data?.enabled === true && Number.isFinite(Number(data.lineHeight)) &&
        Number.isFinite(Number(data.letterSpacing))
        ? normalizedTypography(data) : null;
    } catch (error) {
      console.warn("[Freesia 覆盖侠] 常驻正文排版记录读取失败", error);
      return null;
    }
  }
  let liveTypography = readLiveTypography();
  function persistLiveTypography() {
    try {
      if (liveTypography) WIN.localStorage.setItem(TYPE_LIVE_KEY, JSON.stringify({ enabled: true, ...liveTypography }));
      else WIN.localStorage.removeItem(TYPE_LIVE_KEY);
      return true;
    } catch (error) {
      console.warn("[Freesia 覆盖侠] 保存常驻正文排版失败", error);
      return false;
    }
  }
  function applyLiveTypography() {
    let style = DOC.getElementById(TYPE_LIVE_STYLE_ID);
    if (!liveTypography || state.cleaned) { style?.remove(); return; }
    if (!style) { style = DOC.createElement("style"); style.id = TYPE_LIVE_STYLE_ID; }
    style.textContent = typographyRules(liveTypography);
    // 仅重用同一 style 节点；主题切换后排到主题 CSS 后面，防止被覆盖。
    DOC.head.appendChild(style);
  }

  // § 留白、滚动条、头像定位：仅保存所选值，运行时每项最多一个 style 节点。
  const VALID_SPACING_TARGETS = [".mes_text", ".mes_block", ".mes"];
  const VALID_SCROLL_WIDTHS = ["keep", "3", "4", "5", "6", "7", "8", "9", "10"];
  const VALID_SCROLL_GUTTERS = ["keep", "auto", "stable", "both"];
  const AVATAR_SELECTORS = {
    char: '#sheld#sheld #chat .mes:not([is_user="true"]) .mesAvatarWrapper .avatar img',
    user: '#sheld#sheld #chat .mes[is_user="true"] .mesAvatarWrapper .avatar img',
  };
  const safeAvatarNumber = value => Math.max(0, Math.min(100, Math.round(Number(value) || 0)));
  const normalizeScroll = data => ({
    chatWidth: VALID_SCROLL_WIDTHS.includes(String(data?.chatWidth)) ? String(data.chatWidth) : "keep",
    chatGutter: VALID_SCROLL_GUTTERS.includes(data?.chatGutter) ? data.chatGutter : "keep",
    globalWidth: VALID_SCROLL_WIDTHS.includes(String(data?.globalWidth)) ? String(data.globalWidth) : "keep",
    globalGutter: VALID_SCROLL_GUTTERS.includes(data?.globalGutter) ? data.globalGutter : "keep",
  });
  const normalizeSpacing = data => {
    if (!data || !VALID_SPACING_TARGETS.includes(data.target) ||
        !/^(?:\d+(?:\.\d+)?|\.\d+)(?:px|%|cqi|cqw|vw|em|rem)$/.test(String(data.value))) return null;
    return { target: data.target, value: String(data.value) };
  };
  function loadExtraLive() {
    try {
      const data = JSON.parse(WIN.localStorage.getItem(EXTRA_LIVE_KEY) || "null") || {};
      return {
        spacing: normalizeSpacing(data.spacing),
        scroll: data.scroll && typeof data.scroll === "object" ? normalizeScroll(data.scroll) : null,
        avatar: data.avatar && Number.isFinite(Number(data.avatar.char)) && Number.isFinite(Number(data.avatar.user))
          ? { char: safeAvatarNumber(data.avatar.char), user: safeAvatarNumber(data.avatar.user) } : null,
      };
    } catch (error) {
      console.warn("[Freesia 覆盖侠] 读取实时布局配置失败", error);
      return { spacing: null, scroll: null, avatar: null };
    }
  }
  const extraLive = loadExtraLive();
  function persistExtraLive() {
    try {
      if (extraLive.spacing || extraLive.scroll || extraLive.avatar)
        WIN.localStorage.setItem(EXTRA_LIVE_KEY, JSON.stringify(extraLive));
      else WIN.localStorage.removeItem(EXTRA_LIVE_KEY);
      return true;
    } catch (error) {
      console.warn("[Freesia 覆盖侠] 保存实时布局配置失败", error);
      notifyUser("实时效果已生效，但持久化保存失败；刷新后可能丢失。", "warning");
      return false;
    }
  }
  function setLiveStyle(id, css) {
    let style = DOC.getElementById(id);
    if (!css || state.cleaned) { style?.remove(); return; }
    if (!style) { style = DOC.createElement("style"); style.id = id; }
    if (style.textContent !== css) style.textContent = css;
    // 仅更新同一个 style，不扫描消息节点或循环注入。
    if (!style.isConnected) DOC.head.appendChild(style);
  }
  function applyLiveSpacing() {
    const data = extraLive.spacing;
    setLiveStyle(SPACING_LIVE_STYLE_ID, data
      ? `${getFullSelector(data.target)} { padding-inline: ${data.value} !important; }` : "");
  }
  function avatarRules(data) {
    return `${AVATAR_SELECTORS.char} { object-position: center ${safeAvatarNumber(data.char)}% !important; }\n` +
      `${AVATAR_SELECTORS.user} { object-position: center ${safeAvatarNumber(data.user)}% !important; }`;
  }
  function applyLiveAvatar() { setLiveStyle(AVATAR_LIVE_STYLE_ID, extraLive.avatar ? avatarRules(extraLive.avatar) : ""); }
  const SCROLL_DESKTOP_MEDIA = "@media (hover: hover) and (pointer: fine)";
  const SCROLL_GLOBAL_TARGETS = "html, body, body *:not(#chat):not(#chat *)";
  const SCROLL_CHAT_TARGETS = "html body #sheld#sheld #chat, html body #sheld#sheld #chat *";
  function buildScrollSelections(data) {
    const x = normalizeScroll(data);
    return [
      { id:"scroll-chat-width", value:x.chatWidth, label:"聊天宽度", build: value =>
        `${SCROLL_CHAT_WIDTH_BEGIN}\n${SCROLL_DESKTOP_MEDIA} {\n  ${SCROLL_CHAT_TARGETS.replaceAll(", ", "::-webkit-scrollbar, ")}::-webkit-scrollbar { width: ${value}px !important; height: ${value}px !important; }\n}\n${SCROLL_CHAT_WIDTH_END}` },
      { id:"scroll-chat-gutter", value:x.chatGutter, label:"聊天 Gutter", build: value =>
        `${SCROLL_CHAT_GUTTER_BEGIN}\n${SCROLL_DESKTOP_MEDIA} {\n  ${SCROLL_CHAT_TARGETS} { scrollbar-gutter: ${value === "both" ? "stable both-edges" : value} !important; }\n}\n${SCROLL_CHAT_GUTTER_END}` },
      { id:"scroll-global-width", value:x.globalWidth, label:"全局宽度", build: value =>
        `${SCROLL_GLOBAL_WIDTH_BEGIN}\n${SCROLL_DESKTOP_MEDIA} {\n  ${SCROLL_GLOBAL_TARGETS.replaceAll(", ", "::-webkit-scrollbar, ")}::-webkit-scrollbar { width: ${value}px !important; height: ${value}px !important; }\n}\n${SCROLL_GLOBAL_WIDTH_END}` },
      { id:"scroll-global-gutter", value:x.globalGutter, label:"全局 Gutter", build: value =>
        `${SCROLL_GLOBAL_GUTTER_BEGIN}\n${SCROLL_DESKTOP_MEDIA} {\n  ${SCROLL_GLOBAL_TARGETS} { scrollbar-gutter: ${value === "both" ? "stable both-edges" : value} !important; }\n}\n${SCROLL_GLOBAL_GUTTER_END}` },
    ];
  }
  const selectedScrollFrom = config => buildScrollSelections(config)
    .filter(item => item.value !== "keep")
    .map(item => ({ ...item, block: item.build(item.value) }));
  function applyLiveScroll() {
    const blocks = extraLive.scroll ? selectedScrollFrom(extraLive.scroll) : [];
    setLiveStyle(SCROLL_LIVE_STYLE_ID, blocks.map(item =>
      item.block.replace(/\/\* § FREESIA [^\n]*? · (?:BEGIN|END) \*\//g, "")).join("\n\n"));
  }
  function applyAllExtraLive() {
    applyLiveSpacing();
    applyLiveScroll();
    applyLiveAvatar();
  }

  const WRITE_BEGIN = "/* § 气泡留白测算器 · BEGIN */";
  const WRITE_END = "/* § 气泡留白测算器 · END */";

  const FALLBACK_BTN_ID = `${NS}-button`;
  // 独立脚本入口放在 SillyTavern 底栏扩展菜单（魔法棒）内。
  const MENU_CONTAINER_ID = `${NS}-extension-menu-container`;
  const MENU_ENTRY_ID = `${NS}-extension-menu-entry`;
  let menuObserver = null;
  let menuInstallTimer = null;
  let menuContainer = null;

  const FULL_SELECTOR_MAP = {
    ".mes_text": "#sheld #chat .mes .mes_block .mes_text",
    ".mes_block": "#sheld #chat .mes .mes_block",
    ".mes": "#sheld #chat .mes",
  };

  /* ══════════════════════════════════
   § Freesia Font Library
══════════════════════════════════ */

  const DEFAULT_FONT_PRESETS = [
    {
      id: "clear-han-serif",
      name: "屏显臻宋",
      family: "Clear Han Serif",
      url: "https://fontsapi.zeoseven.com/79/main/result.css",
      weight: "normal",
    },
    {
      id: "sarasa-gothic",
      name: "更纱黑体",
      family: "Sarasa Gothic SC",
      url: "https://fontsapi.zeoseven.com/161/main/result.css",
      weight: "normal",
    },
    {
      id: "frex-sans",
      name: "械黑",
      family: "Frex Sans GB VF",
      url: "https://fontsapi.zeoseven.com/670/main/result.css",
      weight: "normal",
    },
    {
      id: "wenyuan-rounded",
      name: "文渊圆体 SC",
      family: "WenYuan Rounded SC VF",
      url: "https://fontsapi.zeoseven.com/414/main/result.css",
      weight: "normal",
    },
    {
      id: "nano-old-song",
      name: "纳米老宋",
      family: "NanoOldSong-A",
      url: "https://fontsapi.zeoseven.com/467/main/result.css",
      weight: "normal",
    },
    {
      id: "huiwen-mincho",
      name: "汇文明朝体",
      family: "Huiwen-mincho",
      url: "https://fontsapi.zeoseven.com/256/main/result.css",
      weight: "normal",
    },
    {
      id: "kinghwa-old-song",
      name: "京华老宋体",
      family: "KingHwaOldSong",
      url: "https://fontsapi.zeoseven.com/309/main/result.css",
      weight: "normal",
    },
  ];

  /* § Font Library · 本地数据管理 */

  const FONT_STORAGE_KEY = "freesia-theme-composer-fonts-v1";
  const LOCAL_FONT_DB = "FreesiaOverrideFontLibrary";
  const LOCAL_FONT_STORE = "fontFiles";
  const FONT_LIVE_KEY = "freesia-override-live-font-v1";
  const MAX_FONT_MB = 50;

  function formatFontBytes(bytes) {
    return bytes >= 1048576 ? `${(bytes / 1048576).toFixed(1)} MB` : `${Math.ceil(bytes / 1024)} KB`;
  }

  function openFontDatabase() {
    return new Promise((resolve, reject) => {
      if (!WIN.indexedDB) return reject(new Error("当前宿主不支持 IndexedDB，无法保存本地字体。"));
      const request = WIN.indexedDB.open(LOCAL_FONT_DB, 1);
      request.onupgradeneeded = () => {
        const db = request.result;
        if (!db.objectStoreNames.contains(LOCAL_FONT_STORE)) db.createObjectStore(LOCAL_FONT_STORE, { keyPath: "id" });
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error || new Error("字体数据库打开失败"));
      request.onblocked = () => reject(new Error("字体数据库被其他窗口占用，请关闭其他酒馆窗口再试。"));
    });
  }

  async function withFontStore(mode, operation) {
    const db = await openFontDatabase();
    try {
      return await new Promise((resolve, reject) => {
        const tx = db.transaction(LOCAL_FONT_STORE, mode);
        const request = operation(tx.objectStore(LOCAL_FONT_STORE));
        let result;
        request.onsuccess = () => { result = request.result; };
        request.onerror = () => reject(request.error || new Error("字体文件读写失败"));
        tx.oncomplete = () => resolve(result);
        tx.onerror = () => reject(tx.error || new Error("字体数据库事务失败"));
        tx.onabort = () => reject(tx.error || new Error("字体数据库操作已中止"));
      });
    } finally { db.close(); }
  }

  const putLocalFont = record => withFontStore("readwrite", store => store.put(record));
  const getLocalFont = id => withFontStore("readonly", store => store.get(id));
  const removeLocalFont = id => withFontStore("readwrite", store => store.delete(id));

  function loadLiveFontId() {
    try { return JSON.parse(WIN.localStorage.getItem(FONT_LIVE_KEY) || "null")?.fontId || null; }
    catch { return null; }
  }

  let activeLiveFontId = loadLiveFontId();
  let liveFontRunId = 0;
  let currentFontFace = null;
  let currentFontFaceId = null;
  let currentFontObjectUrl = null;

  function saveLiveFontId() {
    try {
      if (activeLiveFontId) WIN.localStorage.setItem(FONT_LIVE_KEY, JSON.stringify({ fontId: activeLiveFontId }));
      else WIN.localStorage.removeItem(FONT_LIVE_KEY);
      return true;
    } catch (error) { log("保存实时字体设置失败", error); return false; }
  }

  // 不能只看文件后缀：部分下载文件实际上是字体集合、压缩包或错误格式。
  async function inspectFontFile(file) {
    const bytes = new Uint8Array(await file.slice(0, 16).arrayBuffer());
    const sig = Array.from(bytes.slice(0, 4), byte => String.fromCharCode(byte)).join("");
    let actualFormat = null;
    if (sig === "wOF2") actualFormat = "woff2";
    else if (sig === "wOFF") actualFormat = "woff";
    else if (sig === "OTTO") actualFormat = "otf";
    else if ((bytes[0] === 0 && bytes[1] === 1 && bytes[2] === 0 && bytes[3] === 0) || sig === "true") actualFormat = "ttf";
    else if (sig === "ttcf") actualFormat = "ttc";
    else if (sig.startsWith("PK")) actualFormat = "zip";
    return { actualFormat, signature: Array.from(bytes.slice(0, 4), x => x.toString(16).padStart(2, "0")).join(" ") };
  }

  // Blob URL 是浏览器常规 @font-face 加载路径；个别宿主与 ArrayBuffer 的解码行为可能不同。
  // 两种路径都失败时，不会把无法显示的文件当作已成功导入。
  async function decodeLocalFont(font, blob) {
    if (!WIN.FontFace) throw new Error("当前宿主不支持 FontFace 字体加载。");
    let urlError;
    if (WIN.URL?.createObjectURL && WIN.URL?.revokeObjectURL) {
      const objectUrl = WIN.URL.createObjectURL(blob);
      try {
        const face = new WIN.FontFace(font.family, `url(${JSON.stringify(objectUrl)})`);
        await face.load();
        return { face, objectUrl, method: "blob-url" };
      } catch (error) {
        urlError = error;
        WIN.URL.revokeObjectURL(objectUrl);
      }
    }
    try {
      const face = new WIN.FontFace(font.family, await blob.arrayBuffer());
      await face.load();
      return { face, objectUrl: null, method: "array-buffer" };
    } catch (bufferError) {
      log("字体解码失败：Blob URL 与 ArrayBuffer 均不支持", {
        name: font.fileName || font.name, urlError, bufferError,
      });
      throw new Error("当前浏览器无法解析该字体（两种加载方式均失败）。可能是字体文件损坏、字体集合或格式不兼容。请换用标准 TTF / OTF / WOFF2 文件。");
    }
  }

  async function importLocalFont(file, panel) {
    if (!file) return;
    const extension = file.name.split(".").pop()?.toLowerCase() || "";
    if (!["woff2", "woff", "ttf", "otf"].includes(extension)) {
      notifyUser("请使用 WOFF2、WOFF、TTF 或 OTF 字体文件。", "error"); return;
    }
    if (!file.size || file.size > MAX_FONT_MB * 1048576) {
      notifyUser(`仅支持不超过 ${MAX_FONT_MB} MB 的有效字体文件。`, "warning"); return;
    }
    if (file.size > 12 * 1048576 && !WIN.confirm(`这个字体有 ${formatFontBytes(file.size)}，可能增加手机内存占用与加载时间。仍要导入吗？`)) return;
    const duplicate = fontPresets.find(font => font.kind === "local" && font.fileName === file.name && font.bytes === file.size);
    if (duplicate) { notifyUser(`字体已存在：${duplicate.name}`, "info"); return; }

    const id = `local-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
    const name = file.name.replace(/\.[^.]+$/, "").trim().slice(0, 72) || "自定义字体";
    const font = { id, name, family: `FreesiaLocal_${id.replace(/[^a-zA-Z0-9_]/g, "_")}`, weight: "normal", kind: "local", bytes: file.size, fileName: file.name, format: extension };
    try {
      const inspection = await inspectFontFile(file);
      if (inspection.actualFormat === "ttc") throw new Error("这是 TTC / OTC 字体集合，不是独立的 TTF / OTF 文件。请先从字体集合导出单独字体。");
      if (inspection.actualFormat === "zip") throw new Error("识别到压缩包内容，请先解压并选择其中的字体文件。");
      if (!inspection.actualFormat) throw new Error(`文件头并非可识别的字体格式（${inspection.signature}）。请确认下载到的是字体本体，而不是网页或其他文件。`);
      if (inspection.actualFormat !== extension) {
        log(`字体后缀与实际格式不符：${file.name}；实际为 ${inspection.actualFormat}`);
        notifyUser(`文件名后缀为 ${extension.toUpperCase()}，实际字体格式为 ${inspection.actualFormat.toUpperCase()}；按真实格式尝试加载。`, "info");
      }
      const loaded = await decodeLocalFont(font, file);
      if (loaded.objectUrl) WIN.URL.revokeObjectURL(loaded.objectUrl);
      await putLocalFont({ id, blob: file, fileName: file.name, bytes: file.size, format: inspection.actualFormat });
      font.format = inspection.actualFormat;
      fontPresets.push(font);
      if (!saveFontPresets()) {
        fontPresets.pop();
        await removeLocalFont(id);
        throw new Error("字体列表保存失败，请检查本地存储空间。");
      }
      renderFontLibrary(panel);
      notifyUser(`已导入：${name}（${formatFontBytes(file.size)}）`, "success");
    } catch (error) {
      log(`字体导入失败：${file.name}`, error);
      notifyUser(`导入失败：${error.message || error}`, "error");
    }
  }

  function loadFontPresets() {
    try {
      const saved = WIN.localStorage.getItem(FONT_STORAGE_KEY);

      if (saved !== null) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) return parsed;
      }
    } catch (err) {
      log("读取字体库失败，使用默认配置", err);
    }

    return DEFAULT_FONT_PRESETS.map((font) => ({ ...font }));
  }

  let fontPresets = loadFontPresets();

  function saveFontPresets() {
    try {
      WIN.localStorage.setItem(FONT_STORAGE_KEY, JSON.stringify(fontPresets));
      return true;
    } catch (err) {
      log("保存字体库失败", err);
      return false;
    }
  }

  function renderFontLibrary(panel) {
    const root = panel?.__tiRoot;
    const list = root?.querySelector(".ti-font-list");
    if (!list) return;
    list.innerHTML = fontPresets.map(font => {
      const local = font.kind === "local";
      const live = font.id === activeLiveFontId;
      const preview = font.id === activeFontPreviewId;
      return `
      <div class="ti-font-card" data-font-id="${esc(font.id)}">
        <div class="ti-font-card-head">
          <div>
            <div class="ti-font-name">${esc(font.name)}</div>
            <div class="ti-font-family">${local ? `本地文件 · ${esc(formatFontBytes(font.bytes || 0))}` : esc(font.family)}</div>
          </div>
          <span class="ti-badge">${local ? "本地" : esc(font.weight || "normal")}</span>
        </div>
        <div class="ti-font-actions">
