  function editFontPreset(font = null) {
    const isNew = !font;
    const sample = font
      ? `@import url("${font.url}");\n\nbody {\n  font-family: "${font.family}";\n  font-weight: ${font.weight || "normal"};\n}`
      : "";
    const pasted = WIN.prompt(
      "粘贴字体网站提供的 CSS 规则（包含 @import 和 font-family 即可）：",
      sample
    );
    if (pasted === null) return;

    const importMatch = pasted.match(/@import\s+url\(\s*(['"]?)(https?:\/\/[^'")\s]+)\1\s*\)\s*;?/i);
    const familyMatch = pasted.match(/font-family\s*:\s*(['"])(.*?)\1\s*;?/i)
      || pasted.match(/font-family\s*:\s*([^;{}]+)\s*;?/i);
    const weightMatch = pasted.match(/font-weight\s*:\s*([^;{}]+)\s*;?/i);

    if (!importMatch || !familyMatch) {
      WIN.alert("没有识别到完整的字体 CSS。请确认内容包含 @import url(...) 和 font-family。");
      return;
    }

    const family = familyMatch[2] ? familyMatch[2].trim() : familyMatch[1].trim();
    const clean = {
      name: family,
      family,
      url: importMatch[2].trim(),
      weight: (weightMatch?.[1] || "normal").trim(),
    };

    if (!clean.family || !clean.url) {
      WIN.alert("未能识别字体名称或字体链接。");
      return;
    }

    try {
      const parsedUrl = new URL(clean.url);
      if (!["http:", "https:"].includes(parsedUrl.protocol)) throw new Error("不支持的链接协议");
    } catch {
      WIN.alert("字体 CSS 链接格式不正确，请检查后重试。");
      return;
    }

    if (isNew) {
      fontPresets.push({
        id: `custom-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
        ...clean,
      });
    } else {
      Object.assign(font, clean);
    }

    if (!saveFontPresets()) {
      WIN.alert("字体库保存失败，请检查浏览器存储空间。");
      return;
    }

    renderFontLibrary(DOC.getElementById(PANEL_ID));
    if (!isNew && activeLiveFontId === font.id) void restorePersistentFont();
    notifyUser(isNew ? `已添加字体方案：${clean.name}` : `已更新字体方案：${clean.name}`, "success");
  }

  async function deleteFontPreset(font) {
    if (!font || !WIN.confirm(`确定删除字体方案「${font.name}」吗？`)) return;
    const prior = fontPresets;
    fontPresets = fontPresets.filter(item => item.id !== font.id);
    WIN.fontPresets = fontPresets;
    if (!saveFontPresets()) {
      fontPresets = prior;
      WIN.fontPresets = fontPresets;
      notifyUser("字体列表保存失败，已取消删除。", "error"); return;
    }
    if (activeLiveFontId === font.id) deactivateLiveFont(false);
    if (activeFontPreviewId === font.id || pendingFontPreviewId === font.id) cancelFontPreview("已删除预览字体，恢复原有字体。");
    if (font.kind === "local") {
      try { await removeLocalFont(font.id); }
      catch (error) { notifyUser(`列表已移除，但删除字体文件失败：${error.message}`, "warning"); }
    }
    renderFontLibrary(DOC.getElementById(PANEL_ID));
    updateFontPreviewUI(DOC.getElementById(PANEL_ID), activeLiveFontId ? "常驻字体仍在使用" : "当前未预览字体", Boolean(activeFontPreviewId));
    notifyUser(`已删除字体方案：${font.name}`, "success");
  }

