  /* ══════════════════════════════════
   § CSS BOX MODEL · 盒模型辅助线
══════════════════════════════════ */

  function createGuideOverlay() {
    if (state.guideOverlay?.isConnected) {
      return state.guideOverlay;
    }

    const overlay = DOC.createElement("div");
    overlay.id = `${NS}-guide-overlay`;

    Object.assign(overlay.style, {
      position: "fixed",
      inset: "0",
      width: "100%",
      height: "100%",
      overflow: "visible",
      pointerEvents: "none",
      zIndex: "4000",
      isolation: "isolate",
    });

    const colors = {
      margin: "rgba(255, 159, 64, .24)",
      padding: "rgba(76, 166, 255, .30)",
      border: "rgba(190, 190, 190, .95)",
      content: "rgba(76, 190, 145, .12)",
    };

    const regions = {};

    [
      "margin-top",
      "margin-bottom",
      "margin-left",
      "margin-right",
      "padding-top",
      "padding-bottom",
      "padding-left",
      "padding-right",
      "border",
      "content",
    ].forEach((name) => {
      const el = DOC.createElement("div");

      Object.assign(el.style, {
        position: "absolute",
        boxSizing: "border-box",
        pointerEvents: "none",
        background: name.startsWith("margin")
          ? colors.margin
          : name.startsWith("padding")
            ? colors.padding
            : name === "content"
              ? colors.content
              : "transparent",
        display: "none",
      });

      if (name === "border") {
        el.style.border = `1px solid ${colors.border}`;
      }

      overlay.appendChild(el);
      regions[name] = el;
    });

    DOC.body.appendChild(overlay);

    state.guideOverlay = overlay;
    // 只创建可见消息需要的辅助线区域，滚动时复用，避免为整份聊天建节点。
    overlay.__regions = regions;
    overlay.__regionPool = [regions];

    return overlay;
  }

  /* 更新单个区域的位置 */
  function setGuideRect(el, left, top, width, height) {
    if (
      !el ||
      ![left, top, width, height].every(Number.isFinite) ||
      width <= 0 ||
      height <= 0
    ) {
      if (el) el.style.display = "none";
      return;
    }

    Object.assign(el.style, {
      display: "block",
      left: `${left}px`,
      top: `${top}px`,
      width: `${width}px`,
      height: `${height}px`,
    });
  }

  /* § 可见楼层辅助线：最多选取 3 条，优先标注可见面积较大的消息。 */
  const MAX_VISIBLE_GUIDES = 3;

  function getGuideTarget(message) {
    if (!message) return null;
    return state.targetSelector === ".mes"
      ? message
      : message.querySelector(state.targetSelector);
  }

  function getVisibleGuideTargets() {
    const chat = DOC.querySelector("#chat");
    if (!chat) return [];
    const chatRect = chat.getBoundingClientRect();
    const top = Math.max(0, chatRect.top);
    const bottom = Math.min(WIN.innerHeight, chatRect.bottom);
    const left = Math.max(0, chatRect.left);
    const right = Math.min(WIN.innerWidth, chatRect.right);
    if (bottom <= top || right <= left) return [];

    const messages = chat.querySelectorAll(".mes");
    // 消息按正常文档流排列；二分查找首个可能在视窗中的楼层，
    // 避免滚动时对历史所有楼层反复测量布局。
    let low = 0, high = messages.length;
    while (low < high) {
      const mid = (low + high) >>> 1;
      if (messages[mid].getBoundingClientRect().bottom <= top) low = mid + 1;
      else high = mid;
    }

    const visible = [];
    for (let i = low; i < messages.length; i++) {
      const messageRect = messages[i].getBoundingClientRect();
      if (messageRect.top >= bottom) break;
      const target = getGuideTarget(messages[i]);
      if (!target) continue;
      const rect = target.getBoundingClientRect();
      const visibleHeight = Math.min(rect.bottom, bottom) - Math.max(rect.top, top);
      const visibleWidth = Math.min(rect.right, right) - Math.max(rect.left, left);
      if (rect.width <= 0 || rect.height <= 0 || visibleHeight <= 0 || visibleWidth <= 0) continue;
      visible.push({ target, top: rect.top, area: visibleHeight * visibleWidth });
    }

    // 长消息优先，避免最后一楼只有几个字时无法比较留白。
    return visible
      .sort((a, b) => b.area - a.area)
      .slice(0, MAX_VISIBLE_GUIDES)
      .sort((a, b) => a.top - b.top)
      .map(item => item.target);
  }

  function getGuideRegionPool(overlay, count) {
    const pool = overlay.__regionPool;
    while (pool.length < count) {
      const regions = {};
      for (const [name, original] of Object.entries(overlay.__regions)) {
        const el = original.cloneNode(false);
        el.style.display = "none";
        overlay.appendChild(el);
        regions[name] = el;
      }
      pool.push(regions);
    }
    return pool;
  }

  /* § 当前可见气泡共享一层辅助线，避免整个聊天 DOM 都挂上辅助元素。 */
  function updateGuideOverlay() {
    if (!state.running || !state.showGuide) {
      removeGuideOverlay();
      return;
    }
    const overlay = createGuideOverlay();
    const targets = getVisibleGuideTargets();
    const pool = getGuideRegionPool(overlay, targets.length);
    for (let i = 0; i < pool.length; i++) {
      const regions = pool[i];
      if (i < targets.length) drawGuideTarget(targets[i], regions);
      else for (const el of Object.values(regions)) el.style.display = "none";
    }
    // 不让聊天之外的辅助线盖住酒馆顶栏、底栏及侧栏。
    const chatRect = DOC.querySelector("#chat")?.getBoundingClientRect();
    if (chatRect) {
      const w = WIN.innerWidth, h = WIN.innerHeight;
      overlay.style.clipPath = `inset(${Math.max(0, chatRect.top)}px ${Math.max(0, w - chatRect.right)}px ${Math.max(0, h - chatRect.bottom)}px ${Math.max(0, chatRect.left)}px)`;
    }
    const status = DOC.getElementById(PANEL_ID)?.__tiRoot?.querySelector(".ti-guide-count");
    if (status) status.textContent = targets.length ? `已标注 ${targets.length}/3 楼` : "当前无可见消息";
  }

  function drawGuideTarget(target, regions) {
    const rect = target.getBoundingClientRect();
    const cs = WIN.getComputedStyle(target);

    const px = (value) => {
      const num = parseFloat(value);
      return Number.isFinite(num) ? num : 0;
    };

    const border = {
      top: px(cs.borderTopWidth),
      right: px(cs.borderRightWidth),
      bottom: px(cs.borderBottomWidth),
      left: px(cs.borderLeftWidth),
    };

    const padding = {
      top: px(cs.paddingTop),
      right: px(cs.paddingRight),
      bottom: px(cs.paddingBottom),
      left: px(cs.paddingLeft),
    };

    const margin = {
      top: Math.max(0, px(cs.marginTop)),
      right: Math.max(0, px(cs.marginRight)),
      bottom: Math.max(0, px(cs.marginBottom)),
      left: Math.max(0, px(cs.marginLeft)),
    };

    const { left, top, width, height } = rect;

    // § Margin：橙色区域
    setGuideRect(
      regions["margin-top"],
      left,
      top - margin.top,
      width,
      margin.top,
    );

    setGuideRect(
      regions["margin-bottom"],
      left,
      top + height,
      width,
      margin.bottom,
    );

    setGuideRect(
      regions["margin-left"],
      left - margin.left,
      top,
      margin.left,
      height,
    );

    setGuideRect(
      regions["margin-right"],
      left + width,
      top,
      margin.right,
      height,
    );

    // § Padding：蓝色区域
    const innerLeft = left + border.left;
    const innerTop = top + border.top;
    const innerWidth = Math.max(0, width - border.left - border.right);
    const innerHeight = Math.max(0, height - border.top - border.bottom);

    setGuideRect(
      regions["padding-top"],
      innerLeft,
      innerTop,
      innerWidth,
      padding.top,
    );

    setGuideRect(
      regions["padding-bottom"],
      innerLeft,
      innerTop + innerHeight - padding.bottom,
      innerWidth,
      padding.bottom,
    );

    setGuideRect(
      regions["padding-left"],
      innerLeft,
      innerTop,
      padding.left,
      innerHeight,
    );

    setGuideRect(
      regions["padding-right"],
      innerLeft + innerWidth - padding.right,
      innerTop,
      padding.right,
      innerHeight,
    );

    // § Border：灰色边界
    setGuideRect(regions.border, left, top, width, height);

    // § Content：绿色区域
    setGuideRect(
      regions.content,
      innerLeft + padding.left,
      innerTop + padding.top,
      innerWidth - padding.left - padding.right,
      innerHeight - padding.top - padding.bottom,
    );
  }

  /* § 合并高频更新请求 */
  function scheduleGuideUpdate() {
    if (!state.showGuide || state.guideRaf !== null) return;

    state.guideRaf = WIN.requestAnimationFrame(() => {
      state.guideRaf = null;
      updateGuideOverlay();
    });
  }

  /* § 开始监听目标尺寸和页面变化 */
  function startGuideObservers() {
    stopGuideObservers();

    const chat = DOC.querySelector("#chat");
    if (!chat) {
      updateGuideOverlay();
      return;
    }

    state.guideAbort = new WIN.AbortController();
    const options = { signal: state.guideAbort.signal };

    // 页面滚动、窗口缩放
    WIN.addEventListener("scroll", scheduleGuideUpdate, {
      ...options,
      capture: true,
    });

    WIN.addEventListener("resize", scheduleGuideUpdate, options);

    WIN.visualViewport?.addEventListener(
      "scroll",
      scheduleGuideUpdate,
      options,
    );

    WIN.visualViewport?.addEventListener(
      "resize",
      scheduleGuideUpdate,
      options,
    );

    // 目标元素和聊天区域尺寸变化
    if (typeof WIN.ResizeObserver === "function") {
      state.guideResizeObserver = new WIN.ResizeObserver(scheduleGuideUpdate);

      // 单独观测滚动容器；子元素变动交给 MutationObserver/scroll 同步。
      state.guideResizeObserver.observe(chat);
    }

    // 消息新增、主题布局及元素属性变化
    if (typeof WIN.MutationObserver === "function" && chat) {
      state.guideMutationObserver = new WIN.MutationObserver(
        scheduleGuideUpdate,
      );

      state.guideMutationObserver.observe(chat, {
        childList: true,
        subtree: true,
        attributes: true,
        attributeFilter: ["class", "style"],
      });
    }

    updateGuideOverlay();
  }

  /* § 停止所有监听 */
  function stopGuideObservers() {
    state.guideAbort?.abort();
    state.guideAbort = null;

    state.guideResizeObserver?.disconnect();
    state.guideResizeObserver = null;

    state.guideMutationObserver?.disconnect();
    state.guideMutationObserver = null;

    if (state.guideRaf !== null) {
      WIN.cancelAnimationFrame(state.guideRaf);
      state.guideRaf = null;
    }
  }

  /* § 清理盒模型覆盖层 */
  function removeGuideOverlay() {
    // 停止所有辅助线监听
    stopGuideObservers();

    // 清除当前覆盖层
    state.guideOverlay?.remove();
    state.guideOverlay = null;

    // 额外清理可能遗留的 DOM
    DOC.getElementById(`${NS}-guide-overlay`)?.remove();
  }

  function setGuideActive(active) {
    state.showGuide = Boolean(active);

    // § 只有测算器运行时才允许显示辅助线
    if (state.showGuide && state.running) {
      createGuideOverlay();
      startGuideObservers();
    } else {
      removeGuideOverlay();
    }

    // 同步最小化胶囊
    const pill = DOC.getElementById(MIN_PILL_ID);
    const gBtn = pill?.querySelector(".mp-guide");

    if (gBtn) {
      gBtn.classList.toggle("on", state.showGuide && state.running);
    }

    // 同步面板复选框
    const panel = DOC.getElementById(PANEL_ID);
    const chk = panel?.__tiRoot?.querySelector(".ti-guide-chk");

    if (chk) {
      chk.checked = state.showGuide;
    }
  }

  function getFullSelector(sel) {
    return FULL_SELECTOR_MAP[sel] || `#sheld #chat ${sel}`;
  }

  function formatUnitValue(pxVal, unit, metrics) {
    if (!metrics)
      return { num: pxVal, text: `${pxVal.toFixed(1)}px`, decimals: 1 };
    let num = pxVal;
    let decimals = 2;
    switch (unit) {
      case "%":
        num = (pxVal / Math.max(1, metrics.percentBaseWidth)) * 100;
        decimals = 2;
        break;
      case "cqi":
      case "cqw":
        num = (pxVal / Math.max(1, metrics.cqBaseWidth)) * 100;
        decimals = 2;
        break;
      case "vw":
        num = (pxVal / Math.max(1, WIN.innerWidth)) * 100;
        decimals = 2;
        break;
      case "em":
        num = pxVal / Math.max(1, metrics.targetFontSize);
        decimals = 2;
        break;
      case "rem":
        num = pxVal / Math.max(1, metrics.rootFontSize);
        decimals = 2;
        break;
      case "px":
      default:
        num = pxVal;
        decimals = 1;
        break;
    }
    return { num, text: `${num.toFixed(decimals)}${unit}`, decimals };
  }

  function unitValueToPx(unitNum, unit, metrics) {
    if (!metrics || Number.isNaN(unitNum)) return 0;
    switch (unit) {
      case "%":
        return (unitNum / 100) * metrics.percentBaseWidth;
      case "cqi":
      case "cqw":
        return (unitNum / 100) * metrics.cqBaseWidth;
      case "vw":
        return (unitNum / 100) * WIN.innerWidth;
      case "em":
        return unitNum * metrics.targetFontSize;
      case "rem":
        return unitNum * metrics.rootFontSize;
      case "px":
      default:
        return unitNum;
    }
  }

  function copyTextCompat(text) {
    const value = String(text ?? "");
    // iOS Safari / TT WebView may not expose navigator.clipboard, or may reject it.
    // execCommand is attempted synchronously inside the original user gesture.
    let temporary = null;
    try {
      temporary = DOC.createElement("textarea");
      temporary.value = value;
      temporary.setAttribute("readonly", "");
      temporary.setAttribute("aria-hidden", "true");
      temporary.style.position = "fixed";
      temporary.style.inset = "0 auto auto 0";
      temporary.style.width = "1px";
      temporary.style.height = "1px";
      temporary.style.padding = "0";
      temporary.style.border = "0";
      temporary.style.opacity = "0.01";
      temporary.style.fontSize = "16px";
      DOC.body.appendChild(temporary);
      temporary.focus({ preventScroll: true });
      temporary.select();
      temporary.setSelectionRange(0, value.length);
      if (typeof DOC.execCommand === "function" && DOC.execCommand("copy")) return true;
    } catch (_) {
      // Continue to the Clipboard API fallback below.
    } finally {
      temporary?.remove();
    }

    try {
      const clipboard = WIN.navigator?.clipboard;
      if (clipboard && typeof clipboard.writeText === "function") {
        return clipboard.writeText(value).then(() => true, () => false);
      }
    } catch (_) { /* Clipboard API unavailable */ }
    return false;
  }

  function buildCopyText(valStr) {
    const fullSel = getFullSelector(state.targetSelector);
    switch (state.copyMode) {
      case "value":
        return valStr;
      case "prop":
        return `padding-inline: ${valStr};`;
      case "prop_imp":
        return `padding-inline: ${valStr} !important;`;
      case "full":
        return `${fullSel} {\n  padding-inline: ${valStr};\n}`;
      case "full_imp":
