  function getCurrentThemeCss(ctx = getStContext()) {
    const settings = ctx?.powerUserSettings;
    if (typeof settings?.custom_css === 'string') return settings.custom_css;
    const style = DOC.getElementById('custom-style');
    if (style?.tagName === 'STYLE') return style.textContent || '';
