  function getCustomCssContext() {
    const st = getStContext();
    const settings = st?.powerUserSettings;
    const native = DOC.getElementById('customCSS');
    const themeSelect = DOC.querySelector('select#themes');
    const saveButton = DOC.getElementById('ui-preset-update-button');
    const themeName = getCurrentThemeName(st);
    const initialCss = getCurrentThemeCss(st);

    if (initialCss === null) {
      throw new Error('无法读取当前主题 CSS。请确认酒馆已加载主题设置后重试。');
    }

    // 提供 textarea-like 接口，让现有区块管理、历史和撤销逻辑保持不变。
    const textarea = {
