  function saveCustomCssContext(ctx) {
    if (!ctx) throw new Error('当前没有可用的 CSS 上下文。');

    // 第一步：先将设置数据写入酒馆的持久化队列。
    const persist = typeof ctx.st?.saveSettingsDebounced === 'function'
      ? () => ctx.st.saveSettingsDebounced()
      : typeof WIN.saveSettingsDebounced === 'function'
        ? () => WIN.saveSettingsDebounced()
        : null;
    if (persist) persist();

    // 第二步：保存主题文件。原生保存按钮可能位于尚未展开的用户设置面板中。
    let saveButton = ctx.saveButton?.isConnected ? ctx.saveButton : DOC.getElementById('ui-preset-update-button');
    let manager = null;
    let restoreVisibility = false;
    let wasVisible = false;

    if (!saveButton) {
      try {
        manager = WIN.__TAURITAVERN_PANEL_RUNTIME__;
        if (typeof manager?.setVisible === 'function' && typeof manager?.reconcile === 'function') {
          const drawer = DOC.getElementById('user-settings-block');
          wasVisible = !!drawer?.classList.contains('openDrawer') && !drawer.classList.contains('closedDrawer');
          manager.setVisible('panel:user-settings-block', true);
          restoreVisibility = true;
          manager.reconcile();
          saveButton = DOC.getElementById('ui-preset-update-button');
        }
      } catch (_) { /* 继续尝试普通 DOM 查找 */ }
    }

    try {
      if (saveButton && saveButton.isConnected && !saveButton.disabled && saveButton.getAttribute('aria-disabled') !== 'true') {
        // display:none 不代表处理器不可用；沿用 CSS Editor 的原生点击方式。
