  /* ══════════════════════════════════
     § FONT INSPECTOR · 字体配置识别
  ══════════════════════════════════ */

  const FONT_TARGET_SELECTORS = [
    "html body #sheld#sheld #chat .mes .mes_block .mes_text",
    "html body #sheld#sheld #chat .mes .mes_block .ch_name .name_text",
    "html body #sheld#sheld #chat .mes .mes_block .mes_reasoning",
    "#left-nav-panel #completion_prompt_manager #completion_prompt_manager_list",
    "#form_sheld #send_form #nonQRFormItems #send_textarea",
    "html",
    "body",
    "select",
    ".options-content",
    "textarea",
  ];

  function inspectThemeFont(cssText) {
    // 移除 CSS 注释，避免干扰选择器识别
    const source = String(cssText || "").replace(/\/\*[\s\S]*?\*\//g, "");

    const result = {
      hasFontImport: false,
      imports: [],
      hasFontMain: false,
      fontMainValue: "",
      hasFontFamilyRules: false,
      matchedSelectors: [],
      unmatchedSelectors: [],
      status: "none",
    };

    // § 识别 @import
    const importPattern =
      /@import\s+(?:url\(\s*)?["']([^"']+)["']\s*\)?[^;]*;/gi;

    let match;

    while ((match = importPattern.exec(source)) !== null) {
      result.imports.push(match[1]);
    }

    result.hasFontImport = result.imports.length > 0;

    // § 识别 --font-main
    const variablePattern = /--font-main\s*:\s*([^;{}]+)\s*;/i;

    const variableMatch = source.match(variablePattern);

    if (variableMatch) {
      result.hasFontMain = true;
      result.fontMainValue = variableMatch[1].trim();
    }

    // § 识别字体规则
    const rulePattern = /([^{}]+)\{([^{}]*)\}/g;

    while ((match = rulePattern.exec(source)) !== null) {
      const selectors = match[1].split(",").map((item) => item.trim());

      const declarations = match[2];

      if (!/\bfont-family\s*:/.test(declarations)) {
        continue;
      }

      result.hasFontFamilyRules = true;

      FONT_TARGET_SELECTORS.forEach((target) => {
        if (
          selectors.some((selector) => selector === target) &&
          !result.matchedSelectors.includes(target)
        ) {
          result.matchedSelectors.push(target);
        }
      });
    }

    result.unmatchedSelectors = FONT_TARGET_SELECTORS.filter(
      (selector) => !result.matchedSelectors.includes(selector),
    );

    // § 判断当前字体配置状态
    if (result.hasFontMain && result.hasFontFamilyRules) {
      result.status = "managed";
    } else if (result.hasFontImport || result.hasFontFamilyRules) {
      result.status = "partial";
    }

    return result;
  }

  /* ══════════════════════════════════
     § FONT CONFIG ENGINE
     字体配置解析与替换
  ══════════════════════════════════ */

  function parseFontConfig(cssText) {
    const source = String(cssText || "");
    const inspected = inspectThemeFont(source);

    // § 定位 :root 中的 --font-main
    const rootPattern = /:root\s*\{([^{}]*)\}/gi;

    let rootMatch;
    let fontVariable = null;

    while ((rootMatch = rootPattern.exec(source)) !== null) {
      const declarations = rootMatch[1];

      const variablePattern = /--font-main\s*:\s*([^;{}]+)\s*;/i;

      const variableMatch = declarations.match(variablePattern);

      if (variableMatch) {
        fontVariable = {
          value: variableMatch[1].trim(),
          rootStart: rootMatch.index,
          rootEnd: rootPattern.lastIndex,
          declarationStart:
            rootMatch.index + rootMatch[0].indexOf(variableMatch[0]),
          declaration: variableMatch[0],
        };

        break;
      }
    }

    return {
      ...inspected,

      rootFound: rootMatch !== null,
      fontVariableFound: Boolean(fontVariable),

      fontVariable,

      canReplace:
        Boolean(fontVariable) && inspected.matchedSelectors.length > 0,
    };
  }

  // § 只替换现有 --font-main，不碰其他变量
  function splitFontFamilyList(value) {
    const source = String(value || "");
    const parts = [];
    let start = 0;
    let quote = null;

    for (let i = 0; i < source.length; i++) {
      const char = source[i];

      if (quote) {
        if (char === quote && source[i - 1] !== "\\") quote = null;
        continue;
      }

      if (char === '"' || char === "'") {
        quote = char;
        continue;
      }

      if (char === ",") {
        parts.push(source.slice(start, i));
        start = i + 1;
      }
    }

    parts.push(source.slice(start));
    return parts;
  }

  // § 只替换第一字体名称，保留原有 fallback 列表
  // § 全局字体只保留目标字体 + serif 通用回退
  function replaceFontMain(cssText, family) {
    const source = String(cssText || "");
    const config = parseFontConfig(source);

    if (!config.fontVariableFound) {
      return {
        success: false,
        reason: "未找到 :root 中的 --font-main，暂不自动修改。",
      };
    }

    const safeFamily = String(family || "").trim();
    if (!safeFamily) {
      return {
        success: false,
        reason: "字体名称不能为空。",
      };
    }

    const escapedFamily = safeFamily
      .replace(/\\/g, "\\\\")
      .replace(/"/g, '\\"');
    const nextValue = `"${escapedFamily}", serif`;
    const replacement = `--font-main: ${nextValue};`;

    const output =
      source.slice(0, config.fontVariable.declarationStart) +
      replacement +
      source.slice(
        config.fontVariable.declarationStart +
          config.fontVariable.declaration.length,
      );

    return {
      success: true,
      css: output,
      previousValue: config.fontVariable.value,
      nextValue,
      preservedFallbacks: ["serif"],
    };
  }

  /* § 替换指定字体导入链接 */
  function replaceFontImport(cssText, oldUrl, newUrl) {
    const source = String(cssText || "");

    if (!oldUrl || !newUrl) {
      return {
        success: false,
        reason: "字体链接不能为空。",
      };
    }

    const escapedUrl = oldUrl.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

    const pattern = new RegExp(
      `(@import\\s+(?:url\\(\\s*)?["'])${escapedUrl}(["']\\s*\\)?[^;]*;)`,
      "g",
    );

    const matches = source.match(pattern);

    if (!matches || matches.length !== 1) {
      return {
        success: false,
        reason: `找到 ${matches?.length || 0} 条匹配导入，拒绝自动替换。`,
      };
    }

    return {
      success: true,
      css: source.replace(pattern, `$1${newUrl}$2`),
    };
  }

  WIN.replaceFontImport = replaceFontImport;

  /* ══════════════════════════════════
   § FONT REPLACEMENT ENGINE
   字体配置组合替换引擎
══════════════════════════════════ */

  function replaceThemeFont(cssText, fontPreset) {
    const source = String(cssText || "");

    if (!fontPreset?.family || !fontPreset?.url) {
      return { success: false, reason: "字体方案缺少名称或 CSS 链接。" };
    }

    const config = parseFontConfig(source);
    if (!config.fontVariableFound) {
      return {
        success: false,
        reason: "没有找到 :root 中的 --font-main，无法安全替换。",
      };
    }

    const oldValue = config.fontVariable.value;
    const oldPrimaryName = splitFontFamilyList(oldValue)[0]
      ?.trim()
      .replace(/^["']|["']$/g, "");

    const oldPrimaryPreset = fontPresets.find(
      (font) => font.family.toLowerCase() === String(oldPrimaryName || "").toLowerCase(),
    );

    let output = source;
    const changes = [];

    const stripComments = (value) =>
      String(value || "").replace(/\/\*[\s\S]*?\*\//g, "");
    const cleanSource = stripComments(source);

    const hasImport = (url, css = output) => {
      const clean = stripComments(css);
      const escaped = url.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      return new RegExp(
        `@import\\s+(?:url\\(\\s*)?["']${escaped}["']`,
        "i",
      ).test(clean);
    };

    // 仅替换可明确识别的旧首选预设字体导入。
    // 若该字体在字体变量以外仍被引用，保留旧导入，避免误伤其他用途。
    if (
      oldPrimaryPreset &&
      oldPrimaryPreset.id !== fontPreset.id &&
      hasImport(oldPrimaryPreset.url)
    ) {
      const escapedFamily = oldPrimaryPreset.family.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      const outsideVariable = cleanSource.replace(
        stripComments(
          source.slice(
            config.fontVariable.declarationStart,
            config.fontVariable.declarationStart +
              config.fontVariable.declaration.length,
          ),
        ),
        "",
      );
      const stillUsedElsewhere = new RegExp(escapedFamily, "i").test(outsideVariable);

      if (!stillUsedElsewhere) {
        const count = (output.match(
          new RegExp(oldPrimaryPreset.url.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "g"),
        ) || []).length;

        if (count === 1) {
          const importResult = replaceFontImport(
            output,
            oldPrimaryPreset.url,
            fontPreset.url,
          );
          if (!importResult.success) return importResult;
          output = importResult.css;
          changes.push("替换旧首选字体导入链接");
        } else if (count > 1) {
          return {
            success: false,
            reason: "旧首选字体导入链接出现多次，拒绝自动替换。",
          };
        }
      }
    }

    if (!hasImport(fontPreset.url, output)) {
      output = `@import url("${fontPreset.url}");\n\n${output}`;
      changes.push("新增目标字体导入链接");
    }

    const variableResult = replaceFontMain(output, fontPreset.family);
    if (!variableResult.success) return variableResult;

    output = variableResult.css;
    changes.push("将 --font-main 设置为目标字体 + serif");

    return {
      success: true,
      css: output,
      previousValue: oldValue,
      nextValue: variableResult.nextValue,
      oldFont: oldPrimaryPreset?.name || "未识别的原字体",
      newFont: fontPreset.name,
      changes,
      changed: output !== source,
    };
  }
  WIN.replaceThemeFont = replaceThemeFont;

  /* § 正式应用字体：仅更新编辑器内容，不自动保存 */
  const FREESIA_FONT_BEGIN = "/* § FREESIA FONT OVERRIDE · BEGIN */";
  const FREESIA_FONT_END = "/* § FREESIA FONT OVERRIDE · END */";
  const FREESIA_FONT_RESOURCES_BEGIN = "/* § FREESIA FONT RESOURCES · BEGIN */";
  const FREESIA_FONT_RESOURCES_END = "/* § FREESIA FONT RESOURCES · END */";

  /* § Freesia CSS Manager · v1.88.5 */
  const FREESIA_CSS_BLOCKS = [
    { id: "spacing", label: "气泡留白", begin: WRITE_BEGIN, end: WRITE_END },
    { id: "typography", label: "正文排版", begin: TYPE_BEGIN, end: TYPE_END },
    { id: "avatar", label: "头像定位", begin: AVATAR_BEGIN, end: AVATAR_END },
    { id: "scroll-width", label: "滚动条宽度", begin: SCROLL_WIDTH_BEGIN, end: SCROLL_WIDTH_END },
    { id: "scroll-chat-width", label: "聊天滚动条宽度", begin: SCROLL_CHAT_WIDTH_BEGIN, end: SCROLL_CHAT_WIDTH_END },
    { id: "scroll-global-width", label: "全局滚动条宽度", begin: SCROLL_GLOBAL_WIDTH_BEGIN, end: SCROLL_GLOBAL_WIDTH_END },
    { id: "scroll-chat-gutter", label: "聊天滚动条 Gutter", begin: SCROLL_CHAT_GUTTER_BEGIN, end: SCROLL_CHAT_GUTTER_END },
    { id: "scroll-global-gutter", label: "全局滚动条 Gutter", begin: SCROLL_GLOBAL_GUTTER_BEGIN, end: SCROLL_GLOBAL_GUTTER_END },
    { id: "chat-layout", label: "聊天布局", begin: SCROLL_LAYOUT_BEGIN, end: SCROLL_LAYOUT_END },
    { id: "font-override", label: "字体覆盖", begin: FREESIA_FONT_BEGIN, end: FREESIA_FONT_END },
    { id: "font-resources", label: "字体资源", begin: FREESIA_FONT_RESOURCES_BEGIN, end: FREESIA_FONT_RESOURCES_END },
  ];

  function scanFreesiaCss(cssText) {
    const css = String(cssText || "");
    const results = FREESIA_CSS_BLOCKS.map((item) => {
      const begins = [...css.matchAll(new RegExp(escapeRegExp(item.begin), "g"))];
      const ends = [...css.matchAll(new RegExp(escapeRegExp(item.end), "g"))];
      if (begins.length === 0 && ends.length === 0) {
        return { ...item, status: "absent", count: 0, blocks: [] };
      }
      if (begins.length !== ends.length || begins.length !== 1 ||
          begins[0].index > ends[0].index) {
        return { ...item, status: "conflict", count: Math.max(begins.length, ends.length), blocks: [] };
      }
      const start = begins[0].index;
      const end = ends[0].index + item.end.length;
      return {
        ...item, status: "managed", count: 1,
        blocks: [{ start, end, text: css.slice(start, end) }],
      };
    });
    return {
      results,
      managedCount: results.filter(x => x.status === "managed").length,
      conflictCount: results.filter(x => x.status === "conflict").length,
      hasConflicts: results.some(x => x.status === "conflict"),
    };
  }

  function escapeRegExp(value) {
    return String(value).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }

  function replaceFreesiaCssBlock(cssText, blockId, newBlock) {
    const css = String(cssText || "");
    const scan = scanFreesiaCss(css);
    const item = scan.results.find(x => x.id === blockId);
    if (!item) throw new Error(`未知的 Freesia CSS 区块：${blockId}`);
    if (item.status === "conflict") {
      throw new Error(`「${item.label}」区块标记重复或不完整。请先使用 Freesia CSS 清理功能。`);
    }
    let base = css;
    if (item.status === "managed") {
      const old = item.blocks[0];
      base = css.slice(0, old.start) + css.slice(old.end);
    }
    const normalized = base.replace(/\s*$/, "");
    if (!newBlock) return base;
    if (blockId === "font-resources") {
      const charset = normalized.match(/^\\s*@charset\\s+["'][^"']+["']\\s*;/i);
      const offset = charset ? charset[0].length : 0;
      return `${normalized.slice(0, offset)}${normalized.slice(offset).trimStart() ? "\n" : ""}${newBlock.trim()}\n${normalized.slice(offset).trimStart()}`;
    }
    return `${normalized}${normalized ? "\n\n" : ""}${newBlock.trim()}\n`;
  }

  function inspectFreesiaCssForCurrentTheme() {
    const ctx = getCustomCssContext();
    return { ctx, scan: scanFreesiaCss(String(ctx.textarea.value || "")) };
  }

  function cleanFreesiaCssForCurrentTheme() {
    const { ctx, scan } = inspectFreesiaCssForCurrentTheme();
    if (scan.hasConflicts) {
      throw new Error("检测到标记损坏或重复。无法安全确定异常区块边界；请先手动检查这些标记。");
    }
    if (!scan.managedCount) return { changed: false, count: 0, themeName: ctx.themeName };
    let next = String(ctx.textarea.value || "");
    const blocks = scan.results
      .filter(x => x.status === "managed")
      .flatMap(x => x.blocks)
      .sort((a, b) => b.start - a.start);
    for (const block of blocks) next = next.slice(0, block.start) + next.slice(block.end);
    dispatchCustomCssInput(ctx.textarea, next, { label: "清理全部 Freesia CSS" });
    return { changed: true, count: blocks.length, themeName: ctx.themeName };
  }



  function removeUnusedKnownFontImports(cssText, targetFontPreset) {
    let css = String(cssText || "");
    const maskComments = (value) =>
      String(value || "").replace(/\/\*[\s\S]*?\*\//g, (comment) =>
        comment.replace(/[^\r\n]/g, " "),
      );
    const importPattern = /@import\s+(?:url\(\s*)?["']([^"']+)["']\s*\)?[^;]*;/gi;
    const removed = [];
    const retained = [];

    for (const font of fontPresets) {
      if (font.id === targetFontPreset.id || font.url === targetFontPreset.url) continue;

      const masked = maskComments(css);
      const matchingImports = [...masked.matchAll(importPattern)]
        .filter((match) => match[1] === font.url);

      if (!matchingImports.length) continue;

      // 只清理字体库中可识别、且主题 CSS 其他位置没有引用的字体。
      // 被变量、font-family 或其他声明引用的字体，以及未知导入，一律保留。
      const withoutImports = masked.replace(importPattern, "");
      const escapedFamily = font.family.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      const familyPattern = new RegExp(escapedFamily, "i");

      if (familyPattern.test(withoutImports)) {
        retained.push(font.name);
        continue;
      }

      // 使用注释遮罩后的原始偏移量，只移除真实 @import，不碰注释内容。
      const ranges = matchingImports
        .map((match) => [match.index, match.index + match[0].length])
        .sort((a, b) => b[0] - a[0]);

      for (const [from, to] of ranges) {
        css = css.slice(0, from) + css.slice(to);
      }
      removed.push(font.name);
    }

    return { css, removed, retained };
  }

  const FREESIA_GLOBAL_FONT_VAR = "freesia-font-family";

  function findCssBlockEnd(source, openIndex) {
    let depth = 1;
    let quote = "";
    let comment = false;
    for (let i = openIndex + 1; i < source.length; i++) {
      const ch = source[i], next = source[i + 1];
      if (comment) {
        if (ch === "*" && next === "/") { comment = false; i++; }
        continue;
      }
      if (quote) {
        if (ch === "\\") { i++; continue; }
        if (ch === quote) quote = "";
        continue;
      }
      if (ch === "/" && next === "*") { comment = true; i++; continue; }
      if (ch === '"' || ch === "'") { quote = ch; continue; }
      if (ch === "{") depth++;
      else if (ch === "}" && --depth === 0) return i;
    }
    return -1;
  }

  function rewriteTopLevelFontDeclarations(body) {
    let quote = "", comment = false, paren = 0, bracket = 0, start = 0;
    const ranges = [];
    for (let i = 0; i <= body.length; i++) {
      const ch = body[i], next = body[i + 1];
      if (comment) {
        if (ch === "*" && next === "/") { comment = false; i++; }
        continue;
      }
      if (quote) {
        if (ch === "\\") { i++; continue; }
        if (ch === quote) quote = "";
        continue;
      }
      if (ch === "/" && next === "*") { comment = true; i++; continue; }
      if (ch === '"' || ch === "'") { quote = ch; continue; }
      if (ch === "(") paren++;
      else if (ch === ")") paren = Math.max(0, paren - 1);
      else if (ch === "[") bracket++;
      else if (ch === "]") bracket = Math.max(0, bracket - 1);
      else if ((ch === ";" || i === body.length) && paren === 0 && bracket === 0) {
        const declaration = body.slice(start, i);
        if (/^\s*(?:font-family|font)\s*:/i.test(declaration)) {
          ranges.push({ start, end: i, property: (declaration.match(/^\s*(font-family|font)\s*:/i) || [,""])[1].toLowerCase() });
        }
        start = i + 1;
      }
    }
    const familyDeclarations = ranges.filter((item) => item.property === "font-family");
    if (!ranges.length) return { body, changed: false };

    // Remove existing font-family declarations, retaining font shorthand and all unrelated declarations.
    let output = body;
    for (const range of familyDeclarations.sort((a,b) => b.start-a.start)) {
      let from = range.start, to = range.end;
      if (output[to] === ";") to++;
      output = output.slice(0, from) + output.slice(to);
    }
    const important = familyDeclarations.some((item) => /!\s*important/i.test(body.slice(item.start,item.end))) ||
      ranges.some((item) => item.property === "font" && /!\s*important/i.test(body.slice(item.start,item.end)));
    const declaration = `\n  font-family: var(--${FREESIA_GLOBAL_FONT_VAR})${important ? " !important" : ""};`;
    return { body: `${output.replace(/\s*$/, "")}${declaration}\n`, changed: true };
  }

  function selectorIsExcluded(selector) {
    const s = selector.toLowerCase();
    if (/::(?:before|after|first-letter|first-line|marker|placeholder|selection)\b/.test(s)) return true;
    if (/(^|[\s.#:[-])(?:fa|fas|far|fab|fal|fad|fa-solid|fa-regular|fa-brands|iconfont|icon-font|material-icons|material-symbols)(?=$|[\s.#:[\]])/.test(s)) return true;
    if (/\[class[*^$|~]?=["'][^"']*(?:^|[\s_-])(?:fa|iconfont|material-icons)(?:[\s_-]|$)/i.test(s)) return true;
    return false;
  }

  function splitSelectorList(selectorText) {
    const parts = [];
    let start = 0, quote = "", paren = 0, bracket = 0;
    for (let i = 0; i < selectorText.length; i++) {
      const ch = selectorText[i];
      if (quote) {
        if (ch === "\\") { i++; continue; }
        if (ch === quote) quote = "";
        continue;
      }
      if (ch === '"' || ch === "'") quote = ch;
      else if (ch === "(") paren++;
      else if (ch === ")") paren = Math.max(0, paren - 1);
      else if (ch === "[") bracket++;
      else if (ch === "]") bracket = Math.max(0, bracket - 1);
      else if (ch === "," && paren === 0 && bracket === 0) {
        parts.push(selectorText.slice(start, i).trim());
        start = i + 1;
      }
    }
    parts.push(selectorText.slice(start).trim());
    return parts.filter(Boolean);
  }

  function takeTopLevelRules(source, report) {
    let output = "", cursor = 0, scan = 0, quote = "", comment = false;
    while (scan < source.length) {
      const ch = source[scan], next = source[scan + 1];
      if (comment) {
        if (ch === "*" && next === "/") { comment = false; scan += 2; } else scan++;
        continue;
      }
      if (quote) {
        if (ch === "\\") { scan += 2; continue; }
        if (ch === quote) quote = "";
        scan++;
        continue;
      }
      if (ch === "/" && next === "*") { comment = true; scan += 2; continue; }
      if (ch === '"' || ch === "'") { quote = ch; scan++; continue; }
      if (ch !== "{") { scan++; continue; }

      const close = findCssBlockEnd(source, scan);
      if (close < 0) {
        report.unparsed++;
        break;
      }
      const prelude = source.slice(cursor, scan);
      const body = source.slice(scan + 1, close);
      const trimmed = prelude.trim();
      let replacementBody = body;

      if (trimmed.startsWith("@")) {
        const atName = (trimmed.match(/^@([\w-]+)/) || [,""])[1].toLowerCase();
        if (["media","supports","container","layer","document","scope"].includes(atName)) {
          const nested = takeTopLevelRules(body, report);
          replacementBody = nested.css;
        } else if (atName === "font-face" || atName.includes("keyframes")) {
          // Font resource declarations and animation frames are intentionally untouched.
        }
      } else {
        const selectors = splitSelectorList(trimmed);
        const rewritten = rewriteTopLevelFontDeclarations(body);
        if (rewritten.changed) {
          if (selectors.length && !selectors.some(selectorIsExcluded)) {
            replacementBody = rewritten.body;
            report.rewritten++;
          } else {
            report.excluded++;
          }
        }
      }

      output += source.slice(cursor, scan + 1) + replacementBody + "}";
      cursor = close + 1;
      scan = close + 1;
    }
    output += source.slice(cursor);
    return { css: output, report };
  }

  function applyGlobalFontTakeover(cssText, fontPreset) {
    const source = String(cssText || "");
    const report = { rewritten: 0, excluded: 0, unparsed: 0 };
    let cleanSource = source;
    const markerStart = cleanSource.indexOf(FREESIA_FONT_BEGIN);
    const markerEnd = cleanSource.indexOf(FREESIA_FONT_END);
    if (markerStart >= 0 && markerEnd > markerStart) {
      cleanSource = cleanSource.slice(0, markerStart) + cleanSource.slice(markerEnd + FREESIA_FONT_END.length);
    }
    const parsed = takeTopLevelRules(cleanSource, report);
    const legacyVariable = new RegExp(`:root\\s*\\{[^}]*--${FREESIA_GLOBAL_FONT_VAR}\\s*:[^}]*\\}`, "g");
    const css = parsed.css.replace(legacyVariable, "").replace(/\\s*$/, "");
    return { success: report.unparsed === 0, css, report };
  }

  function buildFreesiaFontResources(fontPreset) {
    const url = JSON.stringify(fontPreset.url);
    const family = JSON.stringify(fontPreset.family);
    return `${FREESIA_FONT_RESOURCES_BEGIN}
@import url(${url});

:root {
  --${FREESIA_GLOBAL_FONT_VAR}: ${family}, serif;
}
${FREESIA_FONT_RESOURCES_END}`;
  }

  function buildFreesiaFontOverride(fontPreset) {
    const family = JSON.stringify(fontPreset.family);
    const selectors = FONT_TARGET_SELECTORS.join(",\n");
    return `${FREESIA_FONT_BEGIN}\n${selectors} {\n  font-family: ${family}, serif !important;\n  font-weight: normal !important;\n}\n${FREESIA_FONT_END}`;
  }

  function applyFreesiaTopLevelOverride(panel, fontPreset) {
    let ctx;
    try {
      ctx = getCustomCssContext();
    } catch (err) {
      updateFontApplyUI(panel, err.message, true);
      return;
    }

    const originalCss = String(ctx.textarea.value || "");
    const cleanupResult = removeUnusedKnownFontImports(originalCss, fontPreset);
    const block = buildFreesiaFontOverride(fontPreset);
    let nextCss;
    try {
      nextCss = replaceFreesiaCssBlock(cleanupResult.css, "font-override", block);
      nextCss = replaceFreesiaCssBlock(nextCss, "font-resources", buildFreesiaFontResources(fontPreset));
    } catch (err) { updateFontApplyUI(panel, err.message, true); return; }
    if (nextCss === originalCss) {
      updateFontApplyUI(panel, `「${fontPreset.name}」已经是当前顶级覆盖字体，无需重复应用。`);
      return;
    }

    const cleanupSummary = cleanupResult.removed.length
      ? `\n清理未发现其他引用的旧字体导入：${cleanupResult.removed.join("、")}。`
      : "";
    deactivateLiveFont(false);
    dispatchCustomCssInput(ctx.textarea, nextCss);
    state.lastFontApply = {
      themeName: ctx.themeName, originalCss, appliedCss: nextCss,
      fontId: fontPreset.id, fontName: fontPreset.name, mode: "top-level",
    };
    updateFontPreviewUI(panel, `顶级覆盖已应用：${fontPreset.name}`, false);
    updateFontApplyUI(panel, `已追加顶级覆盖规则。${cleanupSummary}尚未保存主题。`, false, true);
  }

  function applyFreesiaOverride(panel, fontPreset) {
    let ctx;
    try {
      ctx = getCustomCssContext();
    } catch (err) {
      updateFontApplyUI(panel, err.message, true);
      return;
    }

    const originalCss = String(ctx.textarea.value || "");
    const cleanupResult = removeUnusedKnownFontImports(originalCss, fontPreset);
    const takeoverResult = applyGlobalFontTakeover(cleanupResult.css, fontPreset);
    if (!takeoverResult.success) {
      updateFontApplyUI(panel, `CSS 扫描遇到 ${takeoverResult.report.unparsed} 处无法配对的规则块。为避免破坏主题，已停止写入。`, true);
      return;
    }

    const block = buildFreesiaFontOverride(fontPreset);
    let nextCss;
    try {
      nextCss = replaceFreesiaCssBlock(takeoverResult.css, "font-override", block);
      nextCss = replaceFreesiaCssBlock(nextCss, "font-resources", buildFreesiaFontResources(fontPreset));
    } catch (err) { updateFontApplyUI(panel, err.message, true); return; }

    if (nextCss === originalCss) {
      updateFontApplyUI(panel, `「${fontPreset.name}」已经是当前覆盖字体，无需重复应用。`);
      return;
    }

    const cleanupSummary = cleanupResult.removed.length
      ? `\n\n将清理确认未在主题 CSS 中继续引用的旧字体导入：${cleanupResult.removed.join("、")}。`
      : "";
        deactivateLiveFont(false);
    dispatchCustomCssInput(ctx.textarea, nextCss);

    state.lastFontApply = {
      themeName: ctx.themeName,
      originalCss,
      appliedCss: nextCss,
      fontId: fontPreset.id,
      fontName: fontPreset.name,
      mode: "force-override",
    };

    updateFontPreviewUI(panel, `覆盖侠已应用：${fontPreset.name}`, false);
    const cleanupMessage = cleanupResult.removed.length
      ? ` 已清理未发现其他引用的旧字体导入：${cleanupResult.removed.join("、")}。`
      : " 未发现可安全自动清理的旧字体导入。";
    updateFontApplyUI(panel, `已接管 ${takeoverResult.report.rewritten} 组字体声明，跳过 ${takeoverResult.report.excluded} 组图标/伪元素规则。${cleanupMessage}尚未保存主题。`, false, true);
  }

  function applyThemeFont(panel, fontPreset) {
    let ctx;
    try {
      ctx = getCustomCssContext();
    } catch (err) {
      updateFontApplyUI(panel, err.message, true);
      return;
    }

    const originalCss = String(ctx.textarea.value || "");
    const result = replaceThemeFont(originalCss, fontPreset);
    if (!result.success) {
      updateFontApplyUI(panel, result.reason || "字体应用失败。", true);
      return;
    }
    if (!result.changed) {
      updateFontApplyUI(panel, `「${fontPreset.name}」已经是当前主题字体，无需重复应用。`);
      return;
    }
    deactivateLiveFont(false);
    dispatchCustomCssInput(ctx.textarea, result.css);

    state.lastFontApply = {
      themeName: ctx.themeName,
      originalCss,
      appliedCss: result.css,
      fontId: fontPreset.id,
      fontName: fontPreset.name,
    };
    updateFontPreviewUI(panel, `已应用：${fontPreset.name}`, false);
    updateFontApplyUI(panel, `已应用「${fontPreset.name}」到「${ctx.themeName}」。尚未保存主题。`, false, true);
  }

  function updateFontApplyUI(panel, message, isError = false, canUndo = Boolean(state.lastFontApply)) {
    const root = panel?.__tiRoot;
    if (!root) return;
    const status = root.querySelector(".ti-font-apply-status");
    const undoBtn = root.querySelector(".ti-font-undo");
    if (status) {
      status.textContent = message;
      status.style.color = isError ? "#ff8a8a" : "";
    }
    if (undoBtn) undoBtn.disabled = !canUndo;
  }



  /* ══════════════════════════════════
   § FONT LIVE PREVIEW
   独立字体实时预览
══════════════════════════════════ */

  const FONT_PREVIEW_LINK_ID = `${NS}-font-preview-link`;
  const FONT_PREVIEW_STYLE_ID = `${NS}-font-preview-style`;

  // § 同一时间只保留一个字体资源、一个运行时样式，避免重复加载。
  let fontPreviewGeneration = 0;
  let activeFontPreviewId = null;
  let pendingFontPreviewId = null;
  let fontPreviewBusy = false;

  function restoreThemeFontPreview() {
    ++fontPreviewGeneration;
    DOC.getElementById(FONT_PREVIEW_STYLE_ID)?.remove();
    DOC.getElementById(FONT_PREVIEW_LINK_ID)?.remove();
    if (currentFontFace) {
      try { DOC.fonts.delete(currentFontFace); } catch (_) { }
      currentFontFace = null;
      currentFontFaceId = null;
    }
    if (currentFontObjectUrl) {
      WIN.URL.revokeObjectURL(currentFontObjectUrl);
      currentFontObjectUrl = null;
    }
  }

  async function previewThemeFont(fontPreset) {
    if (!fontPreset?.family || (fontPreset.kind !== "local" && !fontPreset.url)) {
      return { success: false, reason: "字体方案资料不完整。" };
    }
    restoreThemeFontPreview();
    const generation = fontPreviewGeneration;
    const requestedTheme = DOC.getElementById("themes")?.value || "";
    const isCurrent = () => generation === fontPreviewGeneration &&
      (DOC.getElementById("themes")?.value || "") === requestedTheme && !state.cleaned;
    const quotedFamily = JSON.stringify(fontPreset.family);
    try {
      if (fontPreset.kind === "local") {
        const record = await getLocalFont(fontPreset.id);
        if (!record?.blob) throw new Error("本地字体文件不存在，请重新导入。");
        if (!isCurrent()) return { success: false, cancelled: true };
        if (!WIN.FontFace) throw new Error("当前宿主不支持 FontFace 字体加载。");
        const loaded = await decodeLocalFont(fontPreset, record.blob);
        if (!isCurrent()) {
          if (loaded.objectUrl) WIN.URL.revokeObjectURL(loaded.objectUrl);
          return { success: false, cancelled: true };
        }
        DOC.fonts.add(loaded.face);
        currentFontFace = loaded.face;
        currentFontFaceId = fontPreset.id;
        currentFontObjectUrl = loaded.objectUrl;
      } else {
        const link = DOC.createElement("link");
        link.id = FONT_PREVIEW_LINK_ID;
        link.rel = "stylesheet";
        link.href = fontPreset.url;
        await new Promise((resolve, reject) => {
          link.onload = resolve;
          link.onerror = () => reject(new Error("在线字体 CSS 文件加载失败。"));
          DOC.head.appendChild(link);
        });
        if (!isCurrent()) return { success: false, cancelled: true };
        const faces = await DOC.fonts.load(`16px ${quotedFamily}`);
        if (!isCurrent()) return { success: false, cancelled: true };
        if (!faces.length) throw new Error("未检测到可用字体，请检查字体名称。");
      }
      if (!isCurrent()) return { success: false, cancelled: true };
      const style = DOC.createElement("style");
      style.id = FONT_PREVIEW_STYLE_ID;
      style.textContent = `${FONT_TARGET_SELECTORS.join(",\n")} {\n  font-family: ${quotedFamily} !important;\n  font-weight: normal !important;\n}`;
      DOC.head.appendChild(style);
      return { success: true, family: fontPreset.family, name: fontPreset.name };
    } catch (error) {
      if (!isCurrent()) return { success: false, cancelled: true };
      restoreThemeFontPreview();
      return { success: false, reason: error.message || "字体加载失败。" };
    }
  }

  function updateFontLiveUI(panel) {
    const root = panel?.__tiRoot;
    if (!root) return;
    const font = fontPresets.find(item => item.id === activeLiveFontId);
    const status = root.querySelector(".ti-font-live-status");
    if (status) status.textContent = font ? `使用中：${font.name}` : "未启用 · 跟随主题";
    const off = root.querySelector(".ti-font-live-off");
    if (off) off.disabled = !font;
    root.querySelectorAll('[data-font-action="live"]').forEach(button => {
      const active = button.closest(".ti-font-card")?.dataset.fontId === activeLiveFontId;
      button.classList.toggle("primary", active);
      button.innerHTML = active ? '<i class="fa-solid fa-check"></i> 正在使用' : '<i class="fa-solid fa-bolt"></i> 实时使用';
    });
  }

  async function restorePersistentFont() {
    const runId = ++liveFontRunId;
    const font = fontPresets.find(item => item.id === activeLiveFontId);
    if (!font || state.cleaned) {
      if (activeLiveFontId && !font) { activeLiveFontId = null; saveLiveFontId(); }
      restoreThemeFontPreview();
      updateFontLiveUI(DOC.getElementById(PANEL_ID));
      return;
    }
    const result = await previewThemeFont(font);
    if (runId !== liveFontRunId || state.cleaned) return;
    if (!result.success && !result.cancelled) {
      log(`常驻字体恢复失败：${font.name}`, result.reason);
      notifyUser(`常驻字体加载失败：${result.reason}`, "warning");
      activeLiveFontId = null;
      saveLiveFontId();
    }
    updateFontLiveUI(DOC.getElementById(PANEL_ID));
  }

  async function activatePersistentFont(font, panel) {
    ++liveFontRunId;
    pendingFontPreviewId = null;
    fontPreviewBusy = true;
    updateFontPreviewUI(panel, `正在启用「${font.name}」…`);
    const result = await previewThemeFont(font);
    fontPreviewBusy = false;
    if (result.cancelled) return;
    if (!result.success) {
      updateFontPreviewUI(panel, `实时字体启用失败：${result.reason}`);
      notifyUser(result.reason, "error");
      if (activeLiveFontId) void restorePersistentFont();
      return;
    }
    activeLiveFontId = font.id;
    activeFontPreviewId = null;
    if (!saveLiveFontId()) notifyUser("字体已生效，但持久化设置保存失败。", "warning");
    renderFontLibrary(panel);
    updateFontPreviewUI(panel, `实时字体已启用：${font.name}（不写入 CSS）`);
    notifyUser(`已启用常驻字体：${font.name}`, "success");
  }

  function deactivateLiveFont(notify = true) {
    ++liveFontRunId;
    activeLiveFontId = null;
    activeFontPreviewId = null;
    pendingFontPreviewId = null;
    fontPreviewBusy = false;
    saveLiveFontId();
    restoreThemeFontPreview();
    const panel = DOC.getElementById(PANEL_ID);
    renderFontLibrary(panel);
    updateFontPreviewUI(panel, "实时覆盖已关闭，跟随主题字体");
    if (notify) notifyUser("已关闭实时字体覆盖，恢复主题字体。", "info");
  }

  function updateFontPreviewUI(panel, message, active = false) {
    const root = panel?.__tiRoot;
    if (!root) return;
    const status = root.querySelector(".ti-font-preview-status");
    const restore = root.querySelector(".ti-font-restore");
    if (status) status.textContent = message;
    if (restore) restore.disabled = !active || fontPreviewBusy;
    root.querySelectorAll('[data-font-action="preview"]').forEach(button => {
      const preview = button.closest(".ti-font-card")?.dataset.fontId === activeFontPreviewId;
      button.disabled = fontPreviewBusy;
      button.innerHTML = preview ? '<i class="fa-solid fa-check"></i> 预览中' : '<i class="fa-solid fa-eye"></i> 预览';
    });
  }

  function cancelFontPreview(message = "当前未预览字体", notify = false, restoreLive = true) {
    ++liveFontRunId;
    restoreThemeFontPreview();
    activeFontPreviewId = null;
    pendingFontPreviewId = null;
    fontPreviewBusy = false;
    updateFontPreviewUI(DOC.getElementById(PANEL_ID), message);
    if (restoreLive && activeLiveFontId) void restorePersistentFont();
    if (notify) notifyUser("已取消字体预览。", "info");
  }

  // § 保留现有调试接口；此接口仅用于临时预览，不会改变常驻选择。
  WIN.previewThemeFont = previewThemeFont;
  WIN.restoreThemeFontPreview = restoreThemeFontPreview;

  WIN.fontPresets = fontPresets;

  // § 临时开放控制台测试接口
  WIN.inspectThemeFont = inspectThemeFont;
  WIN.parseFontConfig = parseFontConfig;
  WIN.replaceFontMain = replaceFontMain;

  /* 查找测算器自己的 CSS 标记区 */
  function findManagedCssBlock(cssText) {
    const start = cssText.indexOf(WRITE_BEGIN);
    const end = cssText.indexOf(WRITE_END);

    if (start === -1 && end === -1) return null;

    if (start === -1 || end === -1 || end < start) {
      throw new Error("检测到不完整的 CSS 标记，已停止操作。");
    }

    if (
      cssText.indexOf(WRITE_BEGIN, start + WRITE_BEGIN.length) !== -1 ||
      cssText.indexOf(WRITE_END, end + WRITE_END.length) !== -1
    ) {
      throw new Error("检测到多组 CSS 标记，已停止操作。");
    }

    const blockEnd = end + WRITE_END.length;

    return {
      start,
      end: blockEnd,
      text: cssText.slice(start, blockEnd),
    };
  }

  /* 更新面板状态提示 */
  function updateWriteStatus(panel, message, isError = false) {
    const status = panel?.__tiRoot?.querySelector(".ti-write-status");

    if (!status) return;

    status.textContent = message;
    status.style.color = isError ? "#ff8a8a" : "";
  }

  /* 通过酒馆原生 input 事件更新 CSS */
  function dispatchCustomCssInput(textarea, value, options = {}) {
    const beforeCss = String(textarea.value || "");
    const afterCss = String(value || "");
    if (beforeCss === afterCss) return;

    if (options.record !== false) {
      let themeName = "";
      try { themeName = getCustomCssContext().themeName; } catch (_) {}
      state.cssHistory.push({
        themeName,
        beforeCss,
        afterCss,
        label: options.label || "CSS 修改",
        timestamp: Date.now(),
      });
      if (state.cssHistory.length > 30) state.cssHistory.shift();
      updateGlobalActions();
    }

    textarea.value = afterCss;
    textarea.dispatchEvent(new WIN.Event("input", { bubbles: true }));
  }

  function updateGlobalActions() {
    const root = DOC.getElementById(PANEL_ID)?.__tiRoot;
    if (!root) return;
    const undo = root.querySelector(".ti-global-undo");
    const status = root.querySelector(".ti-global-status");
    const last = state.cssHistory[state.cssHistory.length - 1];
    if (undo) undo.disabled = !last;
    if (status) status.textContent = last
      ? `最近修改：${last.label} · ${state.cssHistory.length} 项可撤销`
      : "当前没有待撤销的 CSS 修改";
  }

  function saveCurrentThemeGlobal() {
    let ctx;
    try { ctx = getCustomCssContext(); }
    catch (err) { WIN.alert(err.message); return; }
    const saveResult = saveCustomCssContext(ctx);
    const root = DOC.getElementById(PANEL_ID)?.__tiRoot;
    const status = root?.querySelector(".ti-global-status");
    const savedTheme = saveResult === "settings-only" ? "CSS 已写回酒馆设置，但未能触发主题文件保存。请打开用户设置 → 主题，手动保存。" : `已提交「${ctx.themeName || "当前主题"}」保存，请留意酒馆的保存提示。`;
    if (status) status.textContent = savedTheme;
    notifyUser(saveResult === "settings-only" ? "CSS 已写回，主题文件尚未保存" : "已提交主题保存", saveResult === "settings-only" ? "warning" : "success");
  }

  function undoLastCssChange() {
    const record = state.cssHistory[state.cssHistory.length - 1];
    if (!record) return;
    let ctx;
    try { ctx = getCustomCssContext(); }
    catch (err) { WIN.alert(err.message); return; }
    if (record.themeName && ctx.themeName && record.themeName !== ctx.themeName) {
      WIN.alert(`最近一次修改属于「${record.themeName}」，当前主题为「${ctx.themeName}」，已阻止撤销。`);
      return;
    }
    if (String(ctx.textarea.value || "") !== record.afterCss) {
      WIN.alert("CSS 在最近一次 Freesia 修改后又发生了变化。为保护手动编辑内容，已停止撤销。");
      return;
    }
    dispatchCustomCssInput(ctx.textarea, record.beforeCss, { record: false });
    state.cssHistory.pop();
    updateGlobalActions();
    const root = DOC.getElementById(PANEL_ID)?.__tiRoot;
    const status = root?.querySelector(".ti-global-status");
    if (status) status.textContent = `已撤销：${record.label}`;
    notifyUser("已撤回覆盖！", "success");
  }

  /* § 一键写入 */
  function writeManagedCss(panel) {
    // 只允许完整规则
    if (!["full", "full_imp"].includes(state.copyMode)) {
      updateWriteStatus(
        panel,
        "请选择完整规则格式，当前格式不支持自动写入。",
        true,
      );
      return;
    }

    if (!state.activeValueStr) {
      updateWriteStatus(panel, "请先拖动留白滑块，或在数字框中输入需要的数值。", true);
      return;
    }

    let ctx;

    try {
      ctx = getCustomCssContext();
    } catch (err) {
      updateWriteStatus(panel, err.message, true);
      return;
    }

    const currentCss = String(ctx.textarea.value || "");

    let existing;

    try {
      existing = findManagedCssBlock(currentCss);
    } catch (err) {
      updateWriteStatus(panel, err.message, true);
      return;
    }

    // 已存在旧规则时，必须确认替换
    if (
      existing &&
      !WIN.confirm("检测到已有测算器留白规则。\n\n确定替换旧规则吗？")
    ) {
      return;
    }

    const rule = buildCopyText(state.activeValueStr);

    const block = `${WRITE_BEGIN}\n${rule}\n${WRITE_END}`;
    let nextCss;
    try { nextCss = replaceFreesiaCssBlock(currentCss, "spacing", block); }
    catch (err) { updateWriteStatus(panel, err.message, true); return; }

    const previousBlock = existing?.text || null;
    const previousStart = existing?.start ?? null;
    dispatchCustomCssInput(ctx.textarea, nextCss, { label: "气泡留白" });

    state.lastWrite = {
      themeName: ctx.themeName,
      block,
      previousBlock,
      previousStart,
    };

    updateWriteStatus(panel, `已写入「${ctx.themeName}」，记得保存当前主题。`);
    notifyUser("正文留白规则写入成功！", "success");
  }

  /* § 保存当前主题 */

  /* § 撤销本次写入 */
    function applyLivePreview(valStr, pxVal = null) {
    ensureStyle();

    const pStyle = DOC.getElementById(PREVIEW_STYLE_ID);

    // 保留用户正在调整的数值
    state.activeValueStr = valStr || "";
    state.activePx = pxVal;

    if (pStyle) {
      // 常驻模式：拖动滑块即时保存并修改同一个 style；暂停测算不清除常驻覆盖。
      if (state.running && valStr && extraLive.spacing) {
        extraLive.spacing = normalizeSpacing({ target: state.targetSelector, value: valStr });
        persistExtraLive();
        applyLiveSpacing();
        pStyle.textContent = "";
      } else {
        pStyle.textContent = state.running && valStr
          ? `${getFullSelector(state.targetSelector)} { padding-inline: ${valStr} !important; }` : "";
      }
    }
    DOC.getElementById(PANEL_ID)?.__tiRoot?.__refreshSpacingLive?.();
    updateMinPillText();
  }

  function autoDetectTarget() {
    const mes =
      DOC.querySelector("#chat .mes:last-child") ||
      DOC.querySelector("#chat .mes");
    if (!mes) return ".mes_text";
    const candidates = [".mes_text", ".mes_block", ".mes"];
    let best = ".mes_text";
    let maxPad = -1;
    for (const sel of candidates) {
      const el = sel === ".mes" ? mes : mes.querySelector(sel);
      if (el) {
        const cs = WIN.getComputedStyle(el);
        const pad =
          (parseFloat(cs.paddingLeft) || 0) +
          (parseFloat(cs.paddingRight) || 0);
        if (pad > maxPad) {
          maxPad = pad;
          best = sel;
        }
      }
    }
    return best;
  }

  function findContainerQueryBaseWidth(el) {
    let cur = el?.parentElement;
    while (cur && cur !== DOC.body && cur !== DOC.documentElement) {
      const cs = WIN.getComputedStyle(cur);
      const cType =
        cs.containerType || cs.getPropertyValue("container-type") || "";
      if (cType && cType !== "normal") {
        const padL = parseFloat(cs.paddingLeft) || 0;
        const padR = parseFloat(cs.paddingRight) || 0;
        const bL = parseFloat(cs.borderLeftWidth) || 0;
        const bR = parseFloat(cs.borderRightWidth) || 0;
        return Math.max(
          1,
          cur.getBoundingClientRect().width - padL - padR - bL - bR,
        );
      }
      cur = cur.parentElement;
    }
    const chatEl =
      DOC.querySelector("#chat") ||
      DOC.querySelector("#sheld") ||
      DOC.documentElement;
    const chatCS = WIN.getComputedStyle(chatEl);
    return Math.max(
      1,
      chatEl.getBoundingClientRect().width -
        (parseFloat(chatCS.paddingLeft) || 0) -
        (parseFloat(chatCS.paddingRight) || 0),
    );
  }

  function computePaddingMetrics(targetSelector) {
    const pStyle = DOC.getElementById(PREVIEW_STYLE_ID);
    const savedPreview = pStyle ? pStyle.textContent : "";
    if (pStyle) pStyle.textContent = "";

    const mesList = DOC.querySelectorAll("#chat .mes");
    const sampleMes = mesList.length > 0 ? mesList[mesList.length - 1] : null;
    if (!sampleMes) {
      if (pStyle) pStyle.textContent = savedPreview;
      return { error: "当前没有检测到聊天消息气泡，请先进入一个聊天窗口。" };
    }

    const targetEl =
      targetSelector === ".mes"
        ? sampleMes
        : sampleMes.querySelector(targetSelector);
    const textEl = sampleMes.querySelector(".mes_text") || targetEl;
    if (!targetEl || !textEl) {
      if (pStyle) pStyle.textContent = savedPreview;
      return { error: `未在当前气泡中找到 ${targetSelector} 容器。` };
    }

    const targetCS = WIN.getComputedStyle(targetEl);
    const textCS = WIN.getComputedStyle(textEl);
    const rootCS = WIN.getComputedStyle(DOC.documentElement);
    const targetRect = targetEl.getBoundingClientRect();

    const parentEl = targetEl.parentElement || sampleMes;
    const parentCS = WIN.getComputedStyle(parentEl);
    const parentRect = parentEl.getBoundingClientRect();
    const percentBaseWidth = Math.max(
      1,
      parentRect.width -
        (parseFloat(parentCS.paddingLeft) || 0) -
        (parseFloat(parentCS.paddingRight) || 0) -
        (parseFloat(parentCS.borderLeftWidth) || 0) -
        (parseFloat(parentCS.borderRightWidth) || 0),
    );

    const cqBaseWidth = findContainerQueryBaseWidth(targetEl);

    const currentPadLeft = parseFloat(targetCS.paddingLeft) || 0;
    const currentPadRight = parseFloat(targetCS.paddingRight) || 0;
    const currentAvgPad = (currentPadLeft + currentPadRight) / 2;

    const fontSize = parseFloat(textCS.fontSize) || 16;
    const targetFontSize = parseFloat(targetCS.fontSize) || fontSize;
    const rootFontSize = parseFloat(rootCS.fontSize) || 16;

    if (pStyle) pStyle.textContent = savedPreview;

    const metrics = {
      fontFamily: textCS.fontFamily.split(",")[0].replace(/['"]/g, ""),
      fontSize,
      targetFontSize,
      rootFontSize,
      containerWidth: targetRect.width,
      percentBaseWidth,
      cqBaseWidth,
      currentPadLeft,
      currentPadRight,
      currentAvgPad,
    };
    state.lastMetrics = metrics;
    return metrics;
  }

