  function syncPanelTheme(panel) {
    // 面板背景直接使用 SmartThemeBlurTintColor，
    // 由 CSS 自动跟随酒馆主题变化。
  }
  /* § 面板配色同步：仅在需要时读取，不持续监听 */
  function watchThemeChanges(panel) {
    syncPanelTheme(panel);
  }
  function layoutPanel(panel) {
    const viewport = WIN.visualViewport;
    const vw = viewport?.width || WIN.innerWidth;
    const vh = viewport?.height || WIN.innerHeight;
    const gutter = 8;
    const panelW = Math.min(480, Math.max(260, vw - gutter * 2));
    const spacingSelected = panel.__tiRoot?.querySelector('.ti-tab[data-tab="spacing"]')?.getAttribute("aria-selected") === "true";
    const compact = state.running && spacingSelected;
    const maxH = compact
      ? Math.min(355, Math.max(240, Math.round(vh * 0.46)))
      : Math.min(680, Math.max(280, Math.round(vh * 0.84)));
    const panelH = Math.min(maxH, vh - gutter * 2);

    const set = (key, value) =>
      panel.style.setProperty(key, value, "important");
    set("width", `${panelW}px`);
    set("height", `${panelH}px`);
    set("max-height", `${panelH}px`);

    if (state.posX === null || state.posY === null) {
      state.posX = Math.max(gutter, vw - panelW - 16);
      state.posY = Math.max(gutter, 58);
    }
    const rectH = panel.offsetHeight || Math.min(360, maxH);
    state.posX = Math.max(gutter, Math.min(vw - panelW - gutter, state.posX));
    state.posY = Math.max(
      gutter,
      Math.min(vh - Math.min(rectH, maxH) - gutter, state.posY),
    );

    set("left", `${state.posX}px`);
    set("top", `${state.posY}px`);
  }

  function makeDraggable(handleEl, moveTargetEl, onPosSave) {
    let pointerId = null;
    let startX = 0;
    let startY = 0;
    let origX = 0;
    let origY = 0;

    handleEl.addEventListener("pointerdown", (e) => {
      if (e.target.closest("button, select, input, label")) return;
      if (e.pointerType === "mouse" && e.button !== 0) return;
      pointerId = e.pointerId;
      const rect = moveTargetEl.getBoundingClientRect();
      startX = e.clientX;
      startY = e.clientY;
      origX = rect.left;
      origY = rect.top;
      handleEl.setPointerCapture(pointerId);
      e.preventDefault();
    });

    handleEl.addEventListener("pointermove", (e) => {
      if (e.pointerId !== pointerId) return;
      const dx = e.clientX - startX;
      const dy = e.clientY - startY;
      const vw = WIN.visualViewport?.width || WIN.innerWidth;
      const vh = WIN.visualViewport?.height || WIN.innerHeight;
      const rect = moveTargetEl.getBoundingClientRect();
      const nextX = Math.max(4, Math.min(vw - rect.width - 4, origX + dx));
      const nextY = Math.max(4, Math.min(vh - rect.height - 4, origY + dy));
      moveTargetEl.style.setProperty("left", `${nextX}px`, "important");
      moveTargetEl.style.setProperty("top", `${nextY}px`, "important");
      moveTargetEl.style.setProperty("right", "auto", "important");
      onPosSave?.(nextX, nextY);
    });

    const endDrag = (e) => {
      if (e.pointerId !== pointerId) return;
      if (handleEl.hasPointerCapture(pointerId))
        handleEl.releasePointerCapture(pointerId);
      pointerId = null;
    };
    handleEl.addEventListener("pointerup", endDrag);
    handleEl.addEventListener("pointercancel", endDrag);
  }

  function updateCustomFeedback(panel, pxVal) {
    const root = panel?.__tiRoot;
    const res = state.lastMetrics;
    if (!root || !res || res.error) return;
    const fb = root.querySelector(".ti-custom-feedback");
    if (!fb) return;
    fb.textContent = `单侧 ${pxVal.toFixed(1)}px · 双侧约 ${(pxVal * 2).toFixed(1)}px`;
  }

  function syncCustomSliderBounds(panel, skipInputText = false) {
    const root = panel?.__tiRoot;
    const res = state.lastMetrics;
    if (!root || !res || res.error) return;
    const slider = root.querySelector(".ti-slider");
    const numInput = root.querySelector(".ti-num-input");
    const unitLabel = root.querySelector(".ti-custom-unit-label");
    if (!slider || !numInput) return;

    const maxPx = Math.max(40, res.containerWidth * 0.35);
    const maxFormatted = formatUnitValue(maxPx, state.unit, res);
    const step =
      state.unit === "px"
        ? 0.5
        : state.unit === "em" || state.unit === "rem"
          ? 0.02
          : 0.05;

    slider.min = "0";
    slider.max = String(Math.ceil(maxFormatted.num * 10) / 10);
    slider.step = String(step);
    numInput.step = String(step);
    if (unitLabel) unitLabel.textContent = state.unit;

    const basePx = state.activePx !== null ? state.activePx : res.currentAvgPad;
    const curFormatted = formatUnitValue(basePx, state.unit, res);
    const valStr = curFormatted.num.toFixed(curFormatted.decimals);
    slider.value = valStr;
    // 只有非用户正在打字时才更新文本框，防止吞小数点和跳光标
    if (!skipInputText && root.activeElement !== numInput) {
      numInput.value = valStr;
    }
    updateCustomFeedback(panel, basePx);
  }

  function renderCalculation(panel) {
    // § 待机状态禁止执行测算
    if (!state.running) return;

    const root = panel.__tiRoot;
    if (!root) return;
    const metricsBox = root.querySelector(".ti-metrics");
    const selectEl = root.querySelector(".ti-target-select");
    const unitEl = root.querySelector(".ti-unit-select");
    state.targetSelector = selectEl.value;
    state.unit = unitEl.value;

    const res = computePaddingMetrics(state.targetSelector);
    if (res.error) {
      metricsBox.innerHTML = `⚠️ ${esc(res.error)}`;
      return;
    }

    const origLUnit = formatUnitValue(res.currentPadLeft, state.unit, res).text;
    const origRUnit = formatUnitValue(
      res.currentPadRight,
      state.unit,
      res,
    ).text;

    metricsBox.innerHTML = `
      <div>字体：<b>${esc(res.fontFamily)}</b> (${res.fontSize.toFixed(1)}px)</div>
      <div>原始留白：左 <b>${origLUnit}</b> (${res.currentPadLeft.toFixed(1)}px) / 右 <b>${origRUnit}</b></div>
    `;

    syncCustomSliderBounds(panel);

  }

  function updateMinPillText() {
    const pill = DOC.getElementById(MIN_PILL_ID);
    if (!pill) return;
    const label = pill.querySelector(".mp-text");
    if (label) {
      label.textContent = state.activeValueStr
        ? `📐 预览: ${state.activeValueStr}`
        : "📐 留白测算 (已最小化)";
    }
  }

  function ensureMinPill() {
    ensureStyle();
    let pill = DOC.getElementById(MIN_PILL_ID);
    if (pill) return pill;
    pill = DOC.createElement("div");
    pill.id = MIN_PILL_ID;
    pill.innerHTML = `
      <span class="mp-text">📐 留白测算</span>
      <button type="button" class="mp-guide ${state.showGuide ? "on" : ""}" title="切换蓝色辅助线">线</button>
      <button type="button" class="mp-expand" title="展开测算面板">展开</button>
    `;
    DOC.body.appendChild(pill);

    makeDraggable(pill, pill, (x, y) => {
      state.pillX = x;
      state.pillY = y;
    });

    pill.querySelector(".mp-guide")?.addEventListener("click", (e) => {
      e.stopPropagation();
      setGuideActive(!state.showGuide);
      const panel = DOC.getElementById(PANEL_ID);
      const chk = panel?.__tiRoot?.querySelector(".ti-guide-chk");
      if (chk) chk.checked = state.showGuide;
    });

    pill.querySelector(".mp-expand")?.addEventListener("click", (e) => {
      e.stopPropagation();
      setMinimized(false);
    });

    return pill;
  }

  function setMinimized(min) {
    state.minimized = Boolean(min);
    const panel = DOC.getElementById(PANEL_ID);
    const pill = ensureMinPill();
    if (state.minimized) {
      if (panel) panel.style.setProperty("display", "none", "important");
      updateMinPillText();
      pill.style.setProperty("display", "inline-flex", "important");
    } else {
      pill.style.setProperty("display", "none", "important");
      if (panel) {
        panel.style.setProperty("display", "flex", "important");
        layoutPanel(panel);

        if (state.running) {
          renderCalculation(panel);
        }
      }
    }
  }

  function ensurePanel() {
    ensureStyle();
    let panel = DOC.getElementById(PANEL_ID);
    if (panel) return panel;

    panel = DOC.createElement("div");
    panel.id = PANEL_ID;
    const fixedStyles = {
      position: "fixed",
      inset: "auto",
      margin: "0",
      padding: "0",
      border: "0",
      height: "auto",
      "min-width": "0",
      "min-height": "0",
      "max-width": "none",
      display: "none",
      overflow: "visible",
      background: "transparent",
      "box-sizing": "border-box",
      "z-index": "4100",
      "align-items": "stretch",
      "justify-content": "flex-start",
      "flex-direction": "column",
    };
    Object.entries(fixedStyles).forEach(([k, v]) =>
      panel.style.setProperty(k, v, "important"),
    );

    const host = DOC.createElement("div");
    const hostStyles = {
      position: "static",
      margin: "0",
      padding: "0",
      border: "0",
      display: "flex",
      "flex-direction": "column",
      width: "100%",
      height: "100%",
      "min-height": "0",
      "max-height": "inherit",
    };
    Object.entries(hostStyles).forEach(([k, v]) =>
      host.style.setProperty(k, v, "important"),
    );
    panel.appendChild(host);

