    // § 居中侠：滚动条布局预览与写入
    const chatScrollWidth = root.querySelector(".ti-chat-width-select");
    const chatScrollGutter = root.querySelector(".ti-chat-gutter-select");
    const globalScrollWidth = root.querySelector(".ti-global-width-select");
    const globalScrollGutter = root.querySelector(".ti-global-gutter-select");
    const scrollStatus = root.querySelector(".ti-scroll-status");
        const scrollDiagnosticResult = root.querySelector(".ti-scroll-diagnostic-result");
    const scrollRuleSources = root.querySelector(".ti-scroll-rule-sources");
    const diagnoseScrollbars = () => {
      const chat = DOC.querySelector("#chat");
      const globalScope = false;
      if (!chat && !globalScope) {
        if (scrollDiagnosticResult) scrollDiagnosticResult.textContent = "未找到 #chat，无法诊断聊天滚动区域。";
        return;
      }
      const scopeRoot = globalScope ? DOC.documentElement : chat;
      const nodes = globalScope
        ? [DOC.documentElement, DOC.body, ...DOC.querySelectorAll("body *")]
        : [scopeRoot, ...scopeRoot.querySelectorAll("*")];
      const candidates = nodes.filter((el, index) => {
        const cs = WIN.getComputedStyle(el);
        const oy = cs.overflowY, ox = cs.overflowX;
        const isRoot = el === DOC.documentElement || el === DOC.body;
        const hasOverflow = el.scrollHeight > el.clientHeight || el.scrollWidth > el.clientWidth;
        const hasScrollMode = ["auto", "scroll", "hidden", "clip"].includes(oy) ||
          ["auto", "scroll", "hidden", "clip"].includes(ox);
        return isRoot || el === chat || (hasScrollMode && hasOverflow);
      }).slice(0, 8);
      const describe = (el) => {
        const cs = WIN.getComputedStyle(el);
        const verticalOverflow = el.scrollHeight > el.clientHeight;
        const horizontalOverflow = el.scrollWidth > el.clientWidth;
        const occupiedW = Math.max(0, el.offsetWidth - el.clientWidth - (parseFloat(cs.borderLeftWidth)||0) - (parseFloat(cs.borderRightWidth)||0));
        const occupiedH = Math.max(0, el.offsetHeight - el.clientHeight - (parseFloat(cs.borderTopWidth)||0) - (parseFloat(cs.borderBottomWidth)||0));
        let pseudo = null;
        try { pseudo = WIN.getComputedStyle(el, "::-webkit-scrollbar"); } catch {}
        let thumb = null, track = null;
        try {
          thumb = WIN.getComputedStyle(el, "::-webkit-scrollbar-thumb");
          track = WIN.getComputedStyle(el, "::-webkit-scrollbar-track");
        } catch {}
        const width = pseudo?.width || "不可读取";
        const height = pseudo?.height || "不可读取";
        const pseudoDisplay = pseudo?.display || "不可读取";
        const pseudoBg = thumb?.backgroundColor || "不可读取";
        const pseudoImage = thumb?.backgroundImage || "不可读取";
        // A transparent background-color does not mean the thumb is invisible:
        // gradients/images may be painted over it.
        const hasPaintedImage = pseudoImage !== "none" && pseudoImage !== "不可读取";
        const transparent = !hasPaintedImage &&
          (/rgba\([^)]*,\s*0\s*\)/.test(pseudoBg) || pseudoBg === "transparent");
        const hiddenByScrollbar = cs.scrollbarWidth === "none" ||
          cs.msOverflowStyle === "none" ||
          pseudoDisplay === "none" || width === "0px" || height === "0px";
        const hiddenByOverflow = cs.overflowY === "clip" || cs.overflowX === "clip" ||
          (cs.overflowY === "hidden" && !verticalOverflow) ||
          (cs.overflowX === "hidden" && !horizontalOverflow);
        const label = el.id ? `#${el.id}` : el.classList?.length ? `${el.tagName.toLowerCase()}.${[...el.classList].slice(0,2).join(".")}` : el.tagName.toLowerCase();
        return {
          label, overflowY:cs.overflowY, overflowX:cs.overflowX,
          verticalOverflow, horizontalOverflow, scrollbarWidth:cs.scrollbarWidth || "auto",
          scrollbarColor:cs.scrollbarColor || "auto", width,height,pseudoDisplay,
          occupiedW,occupiedH,hiddenByScrollbar,hiddenByOverflow,transparent,pseudoBg,pseudoImage,
        };
      };
      const results = candidates.map(describe);
      const primary = results.find(x => x.verticalOverflow || x.horizontalOverflow) || results[0];
      if (scrollDiagnosticResult) {
        scrollDiagnosticResult.textContent = results.map((r,i) =>
          `${i+1}. ${r.label}${r.label === "#chat" ? "（聊天容器）" : ""}\n`+
          `纵向：${r.overflowY}${r.verticalOverflow ? " · 有溢出" : ""}；横向：${r.overflowX}${r.horizontalOverflow ? " · 有溢出" : ""}\n`+
          `scrollbar-width：${r.scrollbarWidth}；scrollbar-color：${r.scrollbarColor}\n`+
          `WebKit：${r.pseudoDisplay}，${r.width} × ${r.height}；滑块背景：${r.transparent ? "透明" : "有背景/图像"}；实际占位：${r.occupiedW}px / ${r.occupiedH}px\n`+
          `判断：${r.hiddenByScrollbar ? "检测到滚动条隐藏规则" : r.transparent ? "可能为透明化隐藏" : r.hiddenByOverflow ? "存在 overflow 限制" : "未发现明确隐藏"}`
        ).join("\n\n");
      }
      // Best-effort CSSOM source tracing. Cross-origin stylesheets are counted as unreadable.
      const matched = new Set();
      let unreadable = 0;
      const inspectRules = (rules) => {
        for (const rule of rules) {
          if (rule.cssRules) { inspectRules(rule.cssRules); continue; }
          if (!rule.selectorText || !rule.style) continue;
          const props = ["scrollbar-width","scrollbar-color","-ms-overflow-style","overflow","overflow-x","overflow-y","width","height","display","background","background-color","opacity"];
          const relevant = props.some(prop => rule.style.getPropertyValue(prop));
          if (!relevant) continue;
          const selectors = rule.selectorText.split(",");
          const hit = selectors.some(sel => {
            const s = sel.trim();
            const isScrollbarPseudo = /::-(?:webkit-scrollbar(?:-thumb|-track|-corner|-track-piece|-button|-resizer)?)/i.test(s);
            const base = s.split("::")[0].trim();

            // Global scrollbar pseudo selectors such as ::-webkit-scrollbar-thumb
            // have an empty base selector and apply to every scroll container.
            if (isScrollbarPseudo) {
              if (!base || base === "*") return true;
              try { return candidates.some(el => el.matches(base)); }
              catch { return false; }
            }

            // In global mode, match page-wide scrollbar pseudo rules as well as
            // ordinary selectors that match discovered scroll containers.
            if (globalScope && (isScrollbarPseudo && (!base || base === "*"))) return true;
            if (!globalScope && s.includes("#chat")) return true;
            try { return candidates.some(el => el.matches(base || s)); }
            catch { return globalScope && isScrollbarPseudo && !base; }
          });
          if (hit) matched.add(`${rule.selectorText} { ${props.filter(prop => rule.style.getPropertyValue(prop)).map(prop => `${prop}: ${rule.style.getPropertyValue(prop)}${rule.style.getPropertyPriority(prop)==="important"?" !important":""}`).join("; ")} }`);
        }
      };
      for (const sheet of [...DOC.styleSheets]) {
        try { inspectRules(sheet.cssRules); } catch { unreadable++; }
      }
      if (scrollRuleSources) {
        const lines = [...matched].slice(0,8);
        scrollRuleSources.textContent = `规则来源（尽力追溯）：${lines.length ? lines.join(" · ") : "未找到可读取的匹配规则"}${unreadable ? `；另有 ${unreadable} 个跨域/受限样式表无法读取` : ""}`;
      }
      return primary;
    };
    root.querySelector(".ti-scroll-diagnose")?.addEventListener("click", diagnoseScrollbars);
    WIN.requestAnimationFrame(() => diagnoseScrollbars());
    WIN.setTimeout(() => diagnoseScrollbars(), 700);
    const getScrollValues = () => ({
