    const selectedScrollBlocks = () => getScrollSelections()
      .filter(item => item.value !== "keep")
      .map(item => ({ ...item, block:item.build(item.value) }));
            const applyScrollPreview = (announce = true) => {
      const blocks = selectedScrollBlocks();
