      if (!style) { style = DOC.createElement("style"); style.id = SCROLL_PREVIEW_STYLE_ID; DOC.head.appendChild(style); }
      style.textContent = blocks.map(item => item.block.replace(/\/\* § FREESIA [^\n]*? · (?:BEGIN|END) \*\//g, "")).join("\n\n");
      if (scrollStatus) scrollStatus.textContent = blocks.length
        ? `正在预览 ${blocks.map(item=>item.label).join("、")}；未选择的项目不变。`
        : "当前四项均为不修改，没有需要预览的内容。";
      if (announce) notifyUser(blocks.length ? "滚动条预览已开启" : "未选择滚动条参数", "info");
      WIN.requestAnimationFrame(() => diagnoseScrollbars());
    };
    const refreshScrollLiveUI = () => {
      const on = Boolean(extraLive.scroll);
      const off = root.querySelector(".ti-scroll-live-off");
