        extraLive.scroll = Object.values(next).every(value => value === "keep") ? null : next;
        persistExtraLive();
        applyLiveScroll();
        DOC.getElementById(SCROLL_PREVIEW_STYLE_ID)?.remove();
        if (!extraLive.scroll && scrollStatus) scrollStatus.textContent = "全部设为不修改，已停止实时覆盖。";
        refreshScrollLiveUI();
      } else if (DOC.getElementById(SCROLL_PREVIEW_STYLE_ID)) applyScrollPreview(false);
    };
