      .forEach(el => el?.addEventListener("change", refreshScrollPreview));
    const setScrollControlValues = config => {
      if (!config) return;
      const x = normalizeScroll(config);
      if (chatScrollWidth) chatScrollWidth.value = x.chatWidth;
      if (chatScrollGutter) chatScrollGutter.value = x.chatGutter;
