      if (globalScrollGutter) globalScrollGutter.value = x.globalGutter;
    };
    if (extraLive.scroll) setScrollControlValues(extraLive.scroll);
    refreshScrollLiveUI();
    root.querySelector(".ti-scroll-preview")?.addEventListener("click", () => {
      if (extraLive.scroll) refreshScrollPreview();
      else applyScrollPreview(true);
    });
    root.querySelector(".ti-scroll-live-on")?.addEventListener("click", () => {
      const data = normalizeScroll(getScrollValues());
      if (Object.values(data).every(value => value === "keep")) {
        notifyUser("请先选择至少一个滚动条参数。", "warning"); return;
      }
      extraLive.scroll = data;
      persistExtraLive();
      DOC.getElementById(SCROLL_PREVIEW_STYLE_ID)?.remove();
      applyLiveScroll();
      refreshScrollLiveUI();
      notifyUser("滚动条常驻覆盖已开启；修改选择项会自动保存。", "success");
    });
    root.querySelector(".ti-scroll-live-off")?.addEventListener("click", () => {
      extraLive.scroll = null;
      persistExtraLive();
      applyLiveScroll();
      DOC.getElementById(SCROLL_PREVIEW_STYLE_ID)?.remove();
      if (scrollStatus) scrollStatus.textContent = "已停用常驻滚动条覆盖，恢复主题原有样式。";
      refreshScrollLiveUI();
      notifyUser("已停用常驻滚动条覆盖", "info");
    });
    root.querySelector(".ti-scroll-cancel")?.addEventListener("click", () => {
      DOC.getElementById(SCROLL_PREVIEW_STYLE_ID)?.remove();
      if (scrollStatus) scrollStatus.textContent = "已取消滚动条预览；写入主题的规则不受影响。";
      notifyUser("已取消滚动条预览", "info");
      WIN.requestAnimationFrame(() => diagnoseScrollbars());
    });
    root.querySelector(".ti-scroll-write")?.addEventListener("click", () => {
      let ctx;
      try { ctx = getCustomCssContext(); }
      catch (err) { if (scrollStatus) scrollStatus.textContent = err.message; notifyUser(err.message, "error"); return; }
      const blocks = selectedScrollBlocks();
      if (!blocks.length) {
        if (scrollStatus) scrollStatus.textContent = "所有项目都是不修改，当前 CSS 保持原样。";
        notifyUser("没有选中需要写入的滚动条参数", "info");
        return;
      }
      const current = String(ctx.textarea.value || "");
      let next = current;
      try {
        // Migration: the legacy chat layout is replaced only when a NEW chat gutter is selected.
        // A legacy mixed-width block cannot be safely split: retain it until explicit cleanup.
        if (blocks.some(item=>item.id === "scroll-chat-gutter")) {
          next = replaceFreesiaCssBlock(next, "chat-layout", "");
        }
        for (const item of blocks) next = replaceFreesiaCssBlock(next, item.id, item.block);
      } catch (err) {
        if (scrollStatus) scrollStatus.textContent = err.message;
        notifyUser(err.message, "error");
        return;
      }
      if (next === current) {
        if (scrollStatus) scrollStatus.textContent = "当前选中参数与 CSS 已有规则一致，无需重复写入。";
        notifyUser("滚动条规则没有变化", "info");
        return;
      }
      dispatchCustomCssInput(ctx.textarea, next, {label:"滚动条参数"});
      DOC.getElementById(SCROLL_PREVIEW_STYLE_ID)?.remove();
      if (scrollStatus) scrollStatus.textContent = `已写入：${blocks.map(item=>item.label).join("、")}；其他项目未修改。`;
      notifyUser("滚动条规则写入成功！", "success");
      WIN.requestAnimationFrame(() => diagnoseScrollbars());
    });

    // § 正文排版参数：行高与字间距
    const lineHeightInput = root.querySelector("#ti-line-height");
    const letterSpacingInput = root.querySelector("#ti-letter-spacing");
    const paragraphIndentSelect = root.querySelector("#ti-paragraph-indent");
    const lineHeightOutput = root.querySelector(".ti-line-height-value");
    const letterSpacingOutput = root.querySelector(".ti-letter-spacing-value");
    const typeStatus = root.querySelector(".ti-type-status");
    const originalLineHeight = root.querySelector(".ti-original-line-height");
    const originalLetterSpacing = root.querySelector(".ti-original-letter-spacing");

    const readOriginalTypography = () => {
      const sample = DOC.querySelector("#chat .mes .mes_block .mes_text");
      if (!sample) {
        if (originalLineHeight) originalLineHeight.textContent = "暂无消息";
        if (originalLetterSpacing) originalLetterSpacing.textContent = "暂无消息";
        return;
      }
      const previewStyle = DOC.getElementById(TYPE_PREVIEW_STYLE_ID);
      const liveStyle = DOC.getElementById(TYPE_LIVE_STYLE_ID);
      const savedPreview = previewStyle?.textContent || "";
      const savedLive = liveStyle?.textContent || "";
      if (previewStyle) previewStyle.textContent = "";
      if (liveStyle) liveStyle.textContent = "";
      let lineHeight, letterSpacing;
      try {
        const computed = WIN.getComputedStyle(sample);
        lineHeight = computed.lineHeight;
        letterSpacing = computed.letterSpacing;
      } finally {
        if (liveStyle) liveStyle.textContent = savedLive;
        if (previewStyle) previewStyle.textContent = savedPreview;
      }
      if (originalLineHeight) originalLineHeight.textContent =
        lineHeight === "normal" ? "normal" : `${Number.parseFloat(lineHeight).toFixed(2)} px`;
      if (originalLetterSpacing) originalLetterSpacing.textContent =
        letterSpacing === "normal" ? "normal (0 px)" : `${Number.parseFloat(letterSpacing).toFixed(2)} px`;
    };

    const getTypeValues = () => normalizedTypography({
      lineHeight: Number(lineHeightInput?.value ?? 1.6),
      letterSpacing: Number(letterSpacingInput?.value ?? 0),
      paragraphIndent: paragraphIndentSelect?.value,
    });
    const updateTypeLabels = () => {
      const values = getTypeValues();
      if (lineHeightOutput) lineHeightOutput.textContent = values.lineHeight.toFixed(2);
      if (letterSpacingOutput) letterSpacingOutput.textContent = `${values.letterSpacing.toFixed(1)} px`;
    };
    const typePreviewStyle = () => DOC.getElementById(TYPE_PREVIEW_STYLE_ID);
    const cancelTypePreview = () => { if (typePreviewStyle()) typePreviewStyle().textContent = ""; };
    const refreshTypeLiveUI = () => {
      const label = root.querySelector(".ti-type-live-status");
      const on = root.querySelector(".ti-type-live-on");
      const stop = root.querySelector(".ti-type-live-stop");
      if (label) label.textContent = liveTypography
        ? `排版实时覆盖：已开启 · 行高 ${liveTypography.lineHeight.toFixed(2)} / 字距 ${liveTypography.letterSpacing.toFixed(1)}px / 缩进 ${liveTypography.paragraphIndent === "2em" ? "2em" : "跟随主题"}`
        : "排版实时覆盖：未启用 · 跟随主题";
      if (on) on.textContent = liveTypography ? "正在实时使用" : "实时使用";
      if (stop) stop.disabled = !liveTypography;
    };
    root.__freesiaRefreshTypeLiveUI = refreshTypeLiveUI;
    if (liveTypography) {
      lineHeightInput.value = String(liveTypography.lineHeight);
      letterSpacingInput.value = String(liveTypography.letterSpacing);
      paragraphIndentSelect.value = liveTypography.paragraphIndent;
    }
    // 临时预览与常驻样式分离：关闭预览时恢复常驻效果，而不是清空它。
    const applyTypePreview = () => {
      ensureStyle();
      const style = typePreviewStyle();
      if (style) {
        style.textContent = typographyRules(getTypeValues());
        DOC.head.appendChild(style); // 预览优先于现有常驻样式
      }
      if (typeStatus) typeStatus.textContent = "正文排版临时预览中；未写入主题 CSS。";
    };
    const enableLiveTypography = (silent = false) => {
      const next = getTypeValues();
      const previous = liveTypography;
      liveTypography = next;
      if (!persistLiveTypography()) {
        liveTypography = previous;
        applyLiveTypography();
        if (typeStatus) typeStatus.textContent = "无法保存常驻排版设置，请检查浏览器存储权限。";
        notifyUser("保存排版设置失败，已取消启用常驻覆盖", "error");
        refreshTypeLiveUI();
        return;
      }
      cancelTypePreview();
      applyLiveTypography();
      refreshTypeLiveUI();
      if (typeStatus) typeStatus.textContent = "正文排版已实时生效；关闭面板与刷新酒馆后仍然保留。";
      if (!silent) notifyUser("正文排版已开启常驻实时覆盖", "success");
    };
    [lineHeightInput, letterSpacingInput, paragraphIndentSelect].forEach(input => {
      input?.addEventListener("input", () => {
        updateTypeLabels();
        if (liveTypography) enableLiveTypography(true);
        else applyTypePreview();
      });
    });
    updateTypeLabels();
    refreshTypeLiveUI();
    readOriginalTypography();
    root.__freesiaRefreshThemeValues?.();
    root.querySelector(".ti-type-refresh")?.addEventListener("click", readOriginalTypography);
    root.querySelector(".ti-type-preview")?.addEventListener("click", () => {
      applyTypePreview();
      notifyUser("已开启正文排版临时预览", "info");
    });
    root.querySelector(".ti-type-restore")?.addEventListener("click", () => {
      cancelTypePreview();
      if (typeStatus) typeStatus.textContent = liveTypography
        ? "已取消临时预览，恢复当前常驻排版。" : "已取消临时预览，恢复主题原始排版。";
      notifyUser("已取消正文排版预览", "info");
    });
    root.querySelector(".ti-type-live-on")?.addEventListener("click", () => enableLiveTypography());
    root.querySelector(".ti-type-live-stop")?.addEventListener("click", () => {
      cancelTypePreview();
      liveTypography = null;
      persistLiveTypography();
      applyLiveTypography();
      refreshTypeLiveUI();
      if (typeStatus) typeStatus.textContent = "常驻排版已关闭；恢复当前主题自身的排版规则。";
      notifyUser("已停用常驻排版，恢复主题样式", "success");
    });
    root.querySelector(".ti-type-apply")?.addEventListener("click", () => {
      let ctx;
      try { ctx = getCustomCssContext(); }
      catch (err) { if (typeStatus) typeStatus.textContent = err.message; return; }
      const originalCss = String(ctx.textarea.value || "");
      let nextCss;
      try {
        nextCss = replaceFreesiaCssBlock(originalCss, "typography", `${TYPE_BEGIN}\n${typographyRules(getTypeValues())}\n${TYPE_END}`);
      } catch (err) { if (typeStatus) typeStatus.textContent = err.message; return; }
      if (nextCss === originalCss) {
        if (typeStatus) typeStatus.textContent = "当前排版规则已写入，无需重复修改。";
        return;
      }
      if (!WIN.confirm(`将行高设为 ${getTypeValues().lineHeight.toFixed(2)}，字间距设为 ${getTypeValues().letterSpacing.toFixed(1)}px，首行缩进：${getTypeValues().paragraphIndent === "2em" ? "2em" : "跟随主题"}？\n\n仅写入以上三项，不包含酒馆字体比例。`)) return;
      dispatchCustomCssInput(ctx.textarea, nextCss, {label:"正文排版与段落缩进"});
      notifyUser("正文排版规则写入成功！", "success");
      cancelTypePreview();
      if (typeStatus) typeStatus.textContent = liveTypography
        ? "排版已写入 CSS；常驻实时覆盖仍开启，可手动停用。记得保存主题。"
        : "排版已写入主题 CSS；尚未保存主题。";
    });

    // § Font Library · 在线方案、本地文件、临时预览与常驻覆盖
    renderFontLibrary(panel);
    const scaleControl = root.querySelector("#ti-font-scale-range");
    const scaleOutput = root.querySelector(".ti-font-scale-value");
    const nativeScale = DOC.querySelector('input[name="font_scale"]#font_scale') || DOC.getElementById("font_scale");
    const syncFontScale = () => {
      const value = Number(nativeScale?.value);
      if (!nativeScale || !Number.isFinite(value)) {
        if (scaleControl) scaleControl.disabled = true;
        if (scaleOutput) scaleOutput.textContent = "不可用";
        return;
      }
      if (scaleControl) { scaleControl.disabled = false; scaleControl.value = String(value); }
      if (scaleOutput) scaleOutput.textContent = `${Math.round(value * 100)}%`;
    };
    root.__freesiaSyncFontScale = syncFontScale;
    syncFontScale();
    nativeScale?.addEventListener("input", syncFontScale);
    DOC.getElementById("font_scale_counter")?.addEventListener("input", () => WIN.setTimeout(syncFontScale, 0));
    scaleControl?.addEventListener("input", () => {
      if (scaleOutput) scaleOutput.textContent = `${Math.round(Number(scaleControl.value) * 100)}%`;
    });
    scaleControl?.addEventListener("change", () => {
      if (!nativeScale || !WIN.jQuery) {
        syncFontScale();
        notifyUser("当前酒馆无法访问原生字体比例事件，已取消修改。", "error");
        return;
      }
      // 使用酒馆自己的监听器：同步 power_user.font_scale、--fontScale 与保存设置。
      WIN.jQuery(nativeScale).val(Number(scaleControl.value)).trigger("input", [{ forced: true }]);
      syncFontScale();
      notifyUser(`酒馆字体比例已调整为 ${Math.round(Number(nativeScale.value) * 100)}%`, "success");
    });

    root.querySelector(".ti-font-add")?.addEventListener("click", () => editFontPreset());
    const fontFileInput = root.querySelector(".ti-font-file-input");
    root.querySelector(".ti-font-import")?.addEventListener("click", () => fontFileInput?.click());
    fontFileInput?.addEventListener("change", async () => {
      const file = fontFileInput.files?.[0];
      fontFileInput.value = "";
      await importLocalFont(file, panel);
    });
    root.querySelector(".ti-font-live-off")?.addEventListener("click", () => deactivateLiveFont());

    root.querySelector(".ti-font-list")?.addEventListener("click", async event => {
      const button = event.target.closest("[data-font-action]");
      if (!button || button.disabled) return;
      const card = button.closest(".ti-font-card");
      const font = fontPresets.find(item => item.id === card?.dataset.fontId);
      if (!font) return;
      switch (button.dataset.fontAction) {
        case "preview": {
          ++liveFontRunId;
          pendingFontPreviewId = font.id;
          activeFontPreviewId = null;
          fontPreviewBusy = true;
          updateFontPreviewUI(panel, `正在加载「${font.name}」…`);
          const result = await previewThemeFont(font);
          if (result.cancelled || pendingFontPreviewId !== font.id) return;
          pendingFontPreviewId = null;
          fontPreviewBusy = false;
          if (result.success) {
            activeFontPreviewId = font.id;
            updateFontPreviewUI(panel, `临时预览：${font.name}（取消后恢复）`, true);
            notifyUser(`正在预览：${font.name}`, "info");
          } else {
            activeFontPreviewId = null;
            updateFontPreviewUI(panel, `预览失败：${result.reason}`);
            notifyUser(result.reason, "error");
            if (activeLiveFontId) void restorePersistentFont();
          }
          return;
        }
        case "live":
          if (activeLiveFontId === font.id && !activeFontPreviewId) deactivateLiveFont();
          else await activatePersistentFont(font, panel);
          return;
        case "apply": {
          if (font.kind === "local") {
            notifyUser("本地字体文件保存在当前设备，不能直接写入主题 CSS，请使用实时覆盖。", "warning");
            return;
          }
          const mode = root.querySelector("#ti-font-apply-mode")?.value || "top-level";
          if (mode === "native") applyThemeFont(panel, font);
          else if (mode === "global") applyFreesiaOverride(panel, font);
          else applyFreesiaTopLevelOverride(panel, font);
          return;
        }
        case "edit":
          if (font.kind !== "local") editFontPreset(font);
          return;
        case "delete":
          await deleteFontPreset(font);
          return;
      }
    });

    root.querySelector(".ti-font-restore")?.addEventListener("click", () => {
      cancelFontPreview("已取消预览，恢复实时使用或主题字体。", true);
    });

    const selectEl = root.querySelector(".ti-target-select");
    const unitEl = root.querySelector(".ti-unit-select");
    const copyModeEl = root.querySelector(".ti-copy-mode");
    const sliderEl = root.querySelector(".ti-slider");
    const numInputEl = root.querySelector(".ti-num-input");

    selectEl.value = state.targetSelector;
    unitEl.value = state.unit;
    copyModeEl.value = state.copyMode;

    selectEl.addEventListener("change", () => {
      applyLivePreview("", null);
      renderCalculation(panel);

      if (state.showGuide) {
        startGuideObservers();
      }
    });

    unitEl.addEventListener("change", () => {
      state.unit = unitEl.value;
      if (state.activePx !== null && state.lastMetrics) {
        const formatted = formatUnitValue(
          state.activePx,
          state.unit,
          state.lastMetrics,
        );
        applyLivePreview(formatted.text, state.activePx);
      }
      renderCalculation(panel);
    });

    copyModeEl.addEventListener("change", () => {
      state.copyMode = copyModeEl.value;
    });

    // 拖动滑块时：同步更新右侧数字框
    sliderEl.addEventListener("input", (e) => {
      const raw = e.currentTarget.value;
      const num = parseFloat(raw);
      if (Number.isNaN(num) || num < 0) return;
      numInputEl.value = raw;
      const pxVal = unitValueToPx(num, state.unit, state.lastMetrics);
      applyLivePreview(`${raw}${state.unit}`, pxVal);
      updateCustomFeedback(panel, pxVal);
    });

    // 手动输入数字时：绝不反向重写 numInputEl.value，彻底避免吃掉小数点和跳光标
    numInputEl.addEventListener("input", (e) => {
      const raw = e.currentTarget.value.trim();
      if (!raw) return;
      const num = parseFloat(raw);
      if (Number.isNaN(num) || num < 0) return;
      sliderEl.value = String(num);
      const pxVal = unitValueToPx(num, state.unit, state.lastMetrics);
      applyLivePreview(`${num}${state.unit}`, pxVal);
      updateCustomFeedback(panel, pxVal);
    });

    root
      .querySelector(".ti-recalc")
      ?.addEventListener("click", () => renderCalculation(panel));
    root
      .querySelector(".ti-min")
      ?.addEventListener("click", () => setMinimized(true));
    root.querySelector(".ti-close")?.addEventListener("click", closePanel);

    root.querySelector(".ti-guide-chk")?.addEventListener("change", (e) => {
      setGuideActive(e.currentTarget.checked);
    });

    root.querySelector(".ti-reset")?.addEventListener("click", () => {
      applyLivePreview("", null);
      renderCalculation(panel);
    });

    root.querySelector(".ti-copy")?.addEventListener("click", (e) => {
      const btn = e.currentTarget;
      if (!state.activeValueStr) {
        notifyUser("请先选择留白数值，再复制。", "warning");
        return;
      }

      const textToCopy = buildCopyText(state.activeValueStr);
      const old = btn.textContent;
      const showSuccess = () => {
        btn.textContent = "已复制 ✔";
        notifyUser("留白 CSS 已复制！", "success");
        WIN.setTimeout(() => { btn.textContent = old; }, 1400);
      };
      const showFailure = () => {
        notifyUser("复制失败，请检查浏览器剪贴板权限。", "error");
      };
      try {
        const result = copyTextCompat(textToCopy);
        if (result && typeof result.then === "function") result.then(ok => ok ? showSuccess() : showFailure());
        else if (result) showSuccess();
        else showFailure();
      } catch (_) { showFailure(); }
    });
    // § 留白常驻：辅助线只属于测算器，不随常驻样式而启动。
    const refreshSpacingLive = () => {
      const on = Boolean(extraLive.spacing);
      const label = root.querySelector(".ti-spacing-live-status");
      const off = root.querySelector(".ti-spacing-live-off");
      if (off) off.disabled = !on;
      if (label) label.textContent = on
        ? `实时留白：${extraLive.spacing.target} / ${extraLive.spacing.value} · 刷新后保留`
        : "实时留白：未启用 · 跟随主题";
    };
    root.__refreshSpacingLive = refreshSpacingLive;
    refreshSpacingLive();
    root.querySelector(".ti-spacing-live-on")?.addEventListener("click", () => {
      if (!state.running) {
        notifyUser("请先启动留白测算，调好数值再点击实时使用。", "warning");
        return;
      }
      const value = state.activeValueStr || `${root.querySelector(".ti-slider")?.value || "0"}${state.unit}`;
      const data = normalizeSpacing({ target: state.targetSelector, value });
      if (!data) { notifyUser("当前留白数值无效，无法实时使用。", "error"); return; }
      extraLive.spacing = data;
      persistExtraLive();
      applyLiveSpacing();
      const preview = DOC.getElementById(PREVIEW_STYLE_ID);
      if (preview) preview.textContent = "";
      refreshSpacingLive();
      notifyUser("留白常驻覆盖已启用；调整滑块将即时保存。", "success");
    });
    root.querySelector(".ti-spacing-live-off")?.addEventListener("click", () => {
      extraLive.spacing = null;
      persistExtraLive();
      applyLiveSpacing();
      const preview = DOC.getElementById(PREVIEW_STYLE_ID);
      if (preview) preview.textContent = "";
      state.activeValueStr = "";
      state.activePx = null;
      refreshSpacingLive();
      if (state.running) renderCalculation(panel);
      notifyUser("已停用常驻留白，恢复主题原有样式。", "info");
    });
    // § 测算器总启停
    root.querySelector(".ti-run-toggle")?.addEventListener("click", () => {
      setRunning(!state.running);
    });
    // § CSS 自动写入
    root.querySelector(".ti-write")?.addEventListener("click", () => {
      writeManagedCss(panel);
    });

    return panel;
  }

  function openPanel() {
    if (state.cleaned) return;

    const panel = ensurePanel();

    syncPanelTheme(panel);
    watchThemeChanges(panel);
    panel.__tiRoot?.__freesiaSyncFontScale?.();
    panel.__tiRoot?.__freesiaRefreshTypeLiveUI?.();
    panel.__tiRoot?.__refreshSpacingLive?.();
    updateFontLiveUI(panel);

    setMinimized(false);

    panel.style.setProperty("display", "flex", "important");
    layoutPanel(panel);

    // § 仅运行状态下执行测算
    if (state.running) {
      const metricsBox = panel.__tiRoot?.querySelector(".ti-metrics");

      if (metricsBox) {
        metricsBox.textContent = "正在读取当前气泡尺寸…";
      }
      renderCalculation(panel);

      if (state.showGuide) {
        startGuideObservers();
      }
    }

    state.panelAbort?.abort();
    state.panelAbort = new WIN.AbortController();

    const options = { signal: state.panelAbort.signal };

    const onResize = () => {
      if (!state.minimized) {
        layoutPanel(panel);
        if (state.running) renderCalculation(panel);
      }
    };

    WIN.addEventListener("resize", onResize, options);
    WIN.visualViewport?.addEventListener("resize", onResize, options);
  }

  /* ══════════════════════════════════
   § 主题切换保护
══════════════════════════════════ */

  function startThemeWatch() {
    stopThemeWatch();

    const themeSelect = DOC.getElementById("themes");

    if (!themeSelect) {
      log("未找到主题选择器，跳过主题切换监听");
      return;
    }

    state.themeChangeHandler = () => {
      state.cssHistory = [];
      updateGlobalActions();
      DOC.getElementById("freesia-live-mes-limit")?.remove();

      // 主题切换清除临时预览；常驻字体按用户明确开启的选择重新恢复。
      cancelFontPreview("主题已切换，已取消临时字体预览。");
      DOC.getElementById(TYPE_PREVIEW_STYLE_ID)?.remove();
      // 常驻正文排版保留，不跟随临时预览一起撤销。
      if (DOC.getElementById(AVATAR_PREVIEW_STYLE_ID)) DOC.getElementById(AVATAR_PREVIEW_STYLE_ID).textContent = "";
      DOC.getElementById(SCROLL_PREVIEW_STYLE_ID)?.remove();
      state.lastFontApply = null;
      state.lastWrite = null;

      const panel = DOC.getElementById(PANEL_ID);
      const root = panel?.__tiRoot;
      if (root) {
        const liveToggle = root.querySelector(".ti-live-enabled");
        if (liveToggle) liveToggle.checked = false;
        root.querySelector(".ti-live-status")?.replaceChildren(DOC.createTextNode("主题已切换，临时正文限高已撤销。"));
        root.querySelector(".ti-type-status")?.replaceChildren(DOC.createTextNode(liveTypography ? "主题已切换，常驻正文排版仍然生效。" : "主题已切换，已取消旧主题排版预览。"));
        root.__freesiaRefreshTypeLiveUI?.();
        root.querySelector(".ti-avatar-status")?.replaceChildren(DOC.createTextNode("主题已切换，已取消旧主题头像预览。"));
        root.__freesiaRefreshThemeValues?.();
      }

      if (state.running) {
        log("检测到主题切换，自动暂停测算器");
        setRunning(false);
      }
      notifyUser("检测到切换主题，所有临时预览效果已清空", "info");
      // 等酒馆完成主题 CSS 替换后重新读取新主题原始值。
      WIN.requestAnimationFrame(() => WIN.requestAnimationFrame(() => {
        root?.__freesiaRefreshThemeValues?.();
        root?.__freesiaSyncFontScale?.();
        root?.querySelector(".ti-scroll-diagnose")?.click();
        WIN.setTimeout(() => root?.__freesiaRefreshThemeValues?.(), 250);
        WIN.setTimeout(() => {
          root?.__freesiaRefreshThemeValues?.();
          root?.__freesiaSyncFontScale?.();
          // CSS 替换完成后保持实时覆盖样式在末尾，不重新请求字体文件。
          const runtimeStyle = DOC.getElementById(FONT_PREVIEW_STYLE_ID);
          if (activeLiveFontId && runtimeStyle) DOC.head.appendChild(runtimeStyle);
          applyLiveTypography();
          applyAllExtraLive();
          // 仅主题真正切换时重新置于新主题 CSS 后面；平时滑块移动不重排 style 节点。
          for (const id of [SPACING_LIVE_STYLE_ID, SCROLL_LIVE_STYLE_ID, AVATAR_LIVE_STYLE_ID]) {
            const style = DOC.getElementById(id);
            if (style?.parentNode === DOC.head) DOC.head.appendChild(style);
          }
          root?.__refreshSpacingLive?.();
          root?.querySelector(".ti-scroll-diagnose")?.click();
        }, 700);
      }));
    };

    themeSelect.addEventListener("change", state.themeChangeHandler);
  }

  /* 停止主题切换监听 */
  function stopThemeWatch() {
    const themeSelect = DOC.getElementById("themes");

    if (themeSelect && state.themeChangeHandler) {
      themeSelect.removeEventListener("change", state.themeChangeHandler);
    }

    state.themeChangeHandler = null;
  }

  /* § 测算器总运行状态 */
  function setRunning(active) {
    state.running = Boolean(active);

    const panel = DOC.getElementById(PANEL_ID);
    const root = panel?.__tiRoot;

    const toggle = root?.querySelector(".ti-run-toggle");
    const status = root?.querySelector(".ti-run-status");

    if (state.running) {
      state.targetSelector = extraLive.spacing?.target || autoDetectTarget();
      // § 启动主题切换监听
      startThemeWatch();

      const select = root?.querySelector(".ti-target-select");
      if (select) select.value = state.targetSelector;

      if (panel) {
        layoutPanel(panel);
        renderCalculation(panel);
      }

      if (state.showGuide) {
        startGuideObservers();
      }

      if (status) {
        status.textContent = "运行中 · 测算与预览已启用";
      }

      if (toggle) {
        toggle.innerHTML =
          "<span style=\"font-family:'Font Awesome 6 Free';font-weight:900\">&#xf04c;</span> 暂停测算器";
        toggle.classList.add("is-running");
      }

      log("测算器已启动");
      return;
    }

    // § 暂停：清除临时效果
    // 主题监听独立于留白测算运行状态，暂停测算也需监听主题切换。
    applyLivePreview("", null);
    removeGuideOverlay();

    state.lastMetrics = null;

    // § 恢复待机提示
    const metricsBox = root?.querySelector(".ti-metrics");

    if (metricsBox) {
      metricsBox.textContent = "启动后自动读取当前气泡尺寸…";
    }

    if (status) {
      status.textContent = "待机中 · 点击启动测算";
    }

    if (toggle) {
      toggle.innerHTML =
        "<span style=\"font-family:'Font Awesome 6 Free';font-weight:900\">&#xf04b;</span> 启动测算器";
      toggle.classList.remove("is-running");
    }

    if (panel && !state.minimized) layoutPanel(panel);
    log("测算器已暂停");
  }

  function closePanel() {
    state.panelAbort?.abort();
    state.panelAbort = null;
    // 临时排版预览随着面板关闭撤销；用户明确启用的常驻排版独立保留。
    const typePreview = DOC.getElementById(TYPE_PREVIEW_STYLE_ID);
    if (typePreview) typePreview.textContent = "";
    if (DOC.getElementById(AVATAR_PREVIEW_STYLE_ID)) DOC.getElementById(AVATAR_PREVIEW_STYLE_ID).textContent = "";
    DOC.getElementById(SCROLL_PREVIEW_STYLE_ID)?.remove();
    // § 关闭面板时清除辅助线，但不强制暂停测算器
    removeGuideOverlay();

    // 隐藏面板，不等于暂停测算器
    const panel = DOC.getElementById(PANEL_ID);

    if (panel) {
      panel.style.setProperty("display", "none", "important");
    }

    const pill = DOC.getElementById(MIN_PILL_ID);

    if (pill) {
      pill.style.setProperty("display", "none", "important");
    }

    state.minimized = false;
  }

  /* § 展折侠：只处理最后一条助手消息中的原生 details */
  const foldAutoOpened = new WeakSet();
  let foldEventsBound = false;
  let foldEnabled = false;

  function getLastAssistantMessage() {
    const messages = Array.from(DOC.querySelectorAll('#chat .mes:not([is_user="true"])'));
    return messages[messages.length - 1] || null;
  }

  function expandLastAssistantDetails() {
    if (!foldEnabled) return;
    const message = getLastAssistantMessage();
    if (!message) return;
    message.querySelectorAll("details").forEach((details) => {
      if (!details.open) {
        details.open = true;
        foldAutoOpened.add(details);
      }
    });
  }

  function collapseAutoOpenedDetails() {
    if (!foldEnabled) return;
    const message = getLastAssistantMessage();
    if (!message) return;
    message.querySelectorAll("details[open]").forEach((details) => {
      if (foldAutoOpened.has(details)) {
        details.open = false;
        foldAutoOpened.delete(details);
      }
    });
  }

  function bindFoldEvents() {
    if (foldEventsBound) return;
    const ctx = (() => { try { return WIN.SillyTavern?.getContext?.() || null; } catch (_) { return null; } })();
    const eventSource = ctx?.eventSource || WIN.eventSource;
    const eventTypes = ctx?.event_types || WIN.event_types;
    if (!eventSource || typeof eventSource.on !== "function" || !eventTypes) {
      log("展折侠：未找到酒馆事件接口，暂不绑定自动管理");
      return;
    }

    const bind = (key, handler) => {
      const type = eventTypes[key];
      if (!type) return false;
      eventSource.on(type, handler);
      return true;
    };

    const generationBound = bind("GENERATION_ENDED", () => {
      WIN.requestAnimationFrame(() => WIN.requestAnimationFrame(expandLastAssistantDetails));
    });
    const userBound = bind("USER_MESSAGE_RENDERED", () => {
      WIN.requestAnimationFrame(collapseAutoOpenedDetails);
    });
    if (generationBound || userBound) {
      foldEventsBound = true;
      log(`展折侠事件已绑定：生成完成=${generationBound}，用户消息=${userBound}`);
    } else {
      log("展折侠：当前酒馆未提供所需事件类型");
    }
  }

  function installExtensionMenuEntry() {
    const attach = () => {
      const menu = DOC.getElementById("extensionsMenu");
      if (!menu) return false;
      if (menuContainer?.isConnected) return true;
      // 防止旧实例异常退出后残留重复菜单项。
      DOC.getElementById(MENU_CONTAINER_ID)?.remove();
      const container = DOC.createElement("div");
      container.id = MENU_CONTAINER_ID;
      container.className = "extension_container";
      const entry = DOC.createElement("div");
      entry.id = MENU_ENTRY_ID;
      entry.className = "list-group-item flex-container flexGap5";
      entry.setAttribute("role", "button");
      entry.setAttribute("tabindex", "0");
      entry.setAttribute("aria-label", "打开 Freesia 覆盖侠");
      entry.innerHTML = '<div class="fa-solid fa-font extensionsMenuExtensionButton" aria-hidden="true"></div><span>Freesia 覆盖侠</span>';
      entry.addEventListener("click", openPanel);
      entry.addEventListener("keydown", event => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          openPanel();
        }
      });
      container.appendChild(entry);
      menu.appendChild(container);
      menuContainer = container;
      DOC.getElementById(FALLBACK_BTN_ID)?.remove();
      return true;
    };

    if (attach()) return;
    if (!DOC.body) {
      DOC.addEventListener("DOMContentLoaded", installExtensionMenuEntry, { once: true });
      return;
    }
    if (menuObserver) return;
    menuObserver = new WIN.MutationObserver(() => {
      if (attach()) {
        menuObserver?.disconnect();
        menuObserver = null;
        if (menuInstallTimer) WIN.clearTimeout(menuInstallTimer);
        menuInstallTimer = null;
      }
    });
    menuObserver.observe(DOC.body, { childList: true, subtree: true });
    menuInstallTimer = WIN.setTimeout(() => {
      menuObserver?.disconnect();
      menuObserver = null;
      menuInstallTimer = null;
      // 非标准酒馆宿主的兜底入口，不在原生扩展菜单存在时占位。
      if (!attach()) ensureFallbackButton();
    }, 15000);
  }

  function ensureFallbackButton() {
    if (DOC.getElementById(FALLBACK_BTN_ID) || DOC.getElementById(MENU_CONTAINER_ID)) return;
    ensureStyle();
    const btn = DOC.createElement("button");
    btn.id = FALLBACK_BTN_ID;
    btn.type = "button";
    btn.title = "Freesia 覆盖侠（扩展菜单不可用时的备用入口）";
    btn.textContent = "覆盖侠";
    btn.addEventListener("click", openPanel);
    DOC.body.appendChild(btn);
  }

  function cleanup() {
    if (state.cleaned) return;
    state.cleaned = true;
    foldEnabled = false;
    if (WIN.__FreesiaOverrideRuntime?.cleanup === cleanup) delete WIN.__FreesiaOverrideRuntime;
    DOC.getElementById("freesia-live-mes-limit")?.remove();
    stopThemeWatch();
    cancelFontPreview();
    closePanel();
    DOC.getElementById(PANEL_ID)?.remove();
    DOC.getElementById(MIN_PILL_ID)?.remove();
    DOC.getElementById(FALLBACK_BTN_ID)?.remove();
    DOC.getElementById(MENU_CONTAINER_ID)?.remove();
    menuContainer = null;
    menuObserver?.disconnect();
    menuObserver = null;
    if (menuInstallTimer) WIN.clearTimeout(menuInstallTimer);
    menuInstallTimer = null;
    DOC.getElementById(STYLE_ID)?.remove();
    DOC.getElementById(PREVIEW_STYLE_ID)?.remove();
    DOC.getElementById(TYPE_PREVIEW_STYLE_ID)?.remove();
    DOC.getElementById(TYPE_LIVE_STYLE_ID)?.remove();
    DOC.getElementById(SPACING_LIVE_STYLE_ID)?.remove();
    DOC.getElementById(SCROLL_LIVE_STYLE_ID)?.remove();
    DOC.getElementById(AVATAR_LIVE_STYLE_ID)?.remove();
    DOC.getElementById(SCROLL_PREVIEW_STYLE_ID)?.remove();
    DOC.getElementById(AVATAR_PREVIEW_STYLE_ID)?.remove();
    ++liveFontRunId;
    restoreThemeFontPreview();
    activeFontPreviewId = null;
    state.lastFontApply = null;
    removeGuideOverlay();
    log("已卸载 Freesia 覆盖侠 1.88.5");
  }

  function init() {
    // 新版重复执行时清理上一实例；TLE 日后也可显式调用 cleanup()。
    try { WIN.__FreesiaOverrideRuntime?.cleanup?.(); } catch (error) { log("旧实例清理失败", error); }
    WIN.__FreesiaOverrideRuntime = {
      cleanup,
      disableFontOverlay: deactivateLiveFont,
      disableLayoutOverlay: (kind) => {
        const kinds = ["spacing", "scroll", "avatar"];
        if (kind && !kinds.includes(kind)) return false;
        for (const key of kinds) if (!kind || kind === key) extraLive[key] = null;
        persistExtraLive();
        applyAllExtraLive();
        return true;
      },
      disableTypographyOverlay: () => {
        liveTypography = null;
        persistLiveTypography();
        applyLiveTypography();
        DOC.getElementById(PANEL_ID)?.__tiRoot?.__freesiaRefreshTypeLiveUI?.();
      },
      entryLocation: "底栏 → 扩展菜单（魔法棒）→ Freesia 覆盖侠",
      independentScript: true,
    };
    ensureStyle();
    applyLiveTypography();
    applyAllExtraLive();
    SCRIPT_WIN.addEventListener("pagehide", cleanup, { once: true });
    SCRIPT_WIN.addEventListener("beforeunload", cleanup, { once: true });
    installExtensionMenuEntry();
    bindFoldEvents();
    if (DOC.readyState === "loading") {
      DOC.addEventListener("DOMContentLoaded", () => {
        startThemeWatch();
        if (activeLiveFontId) void restorePersistentFont();
      }, { once: true });
    } else {
      startThemeWatch();
      if (activeLiveFontId) void restorePersistentFont();
    }
    log("Freesia 覆盖侠 1.88.5 已加载");
  }

  init();
})();
